#region decorator classes
class retryOnEncodeDecodeErrors(SPFGlobals):
    logger = None
    def __init__(self, codecFileScanFlagArgumentName="codecScanFullFile", retryInProgressFlagArgumentName="retryInProgressFlag", finalErrorMessage=None):
        """
        decorator to enable retry on unicode encode errors
        Input Arguments:
        codecFileScanFlagArgumentName : The name of the keyed parameter of the function(E.g., myFunc) that value of which indicates 
                                        True :  perform full file scan for determining the codec
                                        False : (default) performa partial scan for determining the codec
                                        Default value : codecScanFullFile
                                        E.g., myFunc(arg1, arg2, codecScanFullFile=False)
        retryInProgressFlagArgumentName :  The name of the keyed parameter of the function(E.g., myFunc) that value of which indicates 
                                        True :  retry is in progress
                                        False : (default) retry is not in progress
                                        Default value : retryInProgressFlag
        finalErrorMessage : The final custom error message that should be raised on retry completion. Message should have a placeholder to embed the error message

        """
        super(self.__class__, self).__init__()
        loggerName = None
        if retryOnEncodeDecodeErrors.logger is None:    
            retryOnEncodeDecodeErrors.logger  = SPFLogger.GetLogger(loggerName)
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.codecFileScanFlagArgumentName = codecFileScanFlagArgumentName
        self.retryInProgressFlagArgumentName = retryInProgressFlagArgumentName
        self.finalErrorMessage = finalErrorMessage
        self.logger.debug("{0} - codecFileScanFlagArgumentName: {1}".format(calling_func, codecFileScanFlagArgumentName))
        self.logger.debug("{0} - retryInProgressFlagArgumentName: {1}".format(calling_func, retryInProgressFlagArgumentName))
        self.logger.debug("{0} - retryOnEncodeDecodeErrors Initialized".format(calling_func))
        return

    def __call__(self, myFunc):
        """
        This method is internally called when wrapped function is invoked
        Input Arguments:
        myFunc : function object on which this decorator is applied
        Note: the function parameters of 'myFunc' will be available as 'args'(positional parameters) & 'kwargs' (keyed parameters)
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - myFunc.__name__ : {1} --> parameters : {2}".format(calling_func, myFunc.__name__, inspect.signature(myFunc)))
        @functools.wraps(myFunc)
        def wrapped_f(*args, **kwargs):
            doRetry = True
            while True:
                try:
                    return myFunc(*args, **kwargs) #execute the function
                except UnicodeDecodeError as unicodeDecErr: #handle retry only for this type of exception
                    if doRetry is False:
                        if self.finalErrorMessage is not None:
                            raise Exception(finalErrorMessage.format(unicodeDecErr))
                        else:
                            raise
                    else:
                        try: #check if the keyed parameter was already set during invoke
                            _codecFileScanFlagArgumentName_val = kwargs[self.codecFileScanFlagArgumentName]
                        except Exception as err:# not present will cause error
                            _codecFileScanFlagArgumentName_val = None
                        if _codecFileScanFlagArgumentName_val is True:
                            # if initial invoke of function has explicit full-file-scan then no need to retry
                            self.logger.warning("{0} - file-scan-mode value already set {1} = {2}...no retry".format(calling_func, self.codecFileScanFlagArgumentName, _codecFileScanFlagArgumentName_val))
                            raise #argument was already passed to perform full file scan...retry wont help...raise error
                        self.logger.warn("{0} - {1} ...retrying with full-file-scan".format(calling_func, unicodeDecErr))
                        kwargs[self.codecFileScanFlagArgumentName] = True  
                        if self.retryInProgressFlagArgumentName is not None:
                            kwargs[self.retryInProgressFlagArgumentName] = True  
                        doRetry = False # no more retry after full file scan                          
                except Exception as err:
                    if self.finalErrorMessage is not None:
                        raise Exception(finalErrorMessage.format(unicodeDecErr))
                    else:
                        raise
            #END : while True
        #END : def wrapped_f
        return wrapped_f 
    #END : __call__
#END : class retryOnEncodeDecodeErrors
#endregion decorator classes


class Utilities(SPFGlobals):
    """
    Class with utility methods
    """
    logger = None
    vaCoreBaseDir = None
    
