    @property
    def TimeUTCOffset(self):
        """
        #only for local time get UTC/GMT offset in mins
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        retVal = 0
        try :
            mylocalTimezone = dateutil.tz.tzlocal()
            myLocalTimeZoneName = mylocalTimezone.tzname(datetime.now(mylocalTimezone))

            self.logger.info("{0} - TimeZone: {1}".format(calling_func, myLocalTimeZoneName))
            UTCOffsetInSecs = mylocalTimezone.utcoffset(datetime.now(mylocalTimezone)).total_seconds()
            self.logger.info("{0} - UTCOffsetInSeconds: {1}".format(calling_func, UTCOffsetInSecs))
            UTCOffsetInMins = UTCOffsetInSecs / 60 
            self.logger.info("{0} - UTCOffsetInMinutes: {1}".format(calling_func, UTCOffsetInMins))
            retVal = UTCOffsetInMins
            return retVal
        except Exception as err:
            self.logger.error("{0} - {1}".format(calling_func, err.args[0]))
            raise

