    # status : Dev WIP
    def DoOpenFile(self, MyFile, MyMode, Retry = False, MyText = None):
        """
        '===================
        'Open file. Return False
        'if err
        '
        'INPUT :
        '-------
        ' 1.) MyFile : StringType : File to Open
        ' 2.) MyMode : IntegerType : 1=>Err if File ~Found or ~exists
        ' 3.) Retry : BooleanType : If True perform retry else no retry
        ' 4.) MyText : StringType : Notes for err msg
        '        Default = None
        ' 
        'OUTPUT : (multiple)
        '-------------------
        ' 1.) DoOpenFileStatus : BooleanType : Status of function execution
        ' 2.) fileObj : ObjectType : File object if was open
        '
        'ON ERROR :
        '---------
        ' 1.) set gMyAbort:Y=fatal err
        ' 2.) raise error
        '
        'Note : 'ObjFile : File Ref # dropped Py doesn't support byRef
        '
        '===================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("MyFile = {0}\nMyMode = {1}\nRetry = {2}\nMyText = {3}".format(MyFile, MyMode, Retry, MyText))
        DoOpenFileStatus = False # assume failed to open file
        fileObj = None
        maxRetryCount = 3
        myRetryCount = 1
        retrySleep = 3 #seconds

        try :
            if MyFile is None or len(MyFile.strip()) == 0:
                raise Exception("No file argument passed ...")

            MyFile = os.path.abspath(MyFile.strip())

            if os.path.exists(MyFile) == False:
                raise Exception("File {0} does not exist...".format(MyFile))

            while DoOpenFileStatus == False :
                try :
                    fileObj = open(MyFile, "r")           # if isPYTHON2 else 'r'
                    DoOpenFileStatus = True
                except Exception as err:
                    if Retry == True and myRetryCount < maxRetryCount:
                        myRetryCount = myRetryCount + 1
                        time.sleep(retrySleep)
                    else :
                        raise 
            self.logger.debug("DoOpenFileStatus = {0}".format(DoOpenFileStatus))
            return DoOpenFileStatus, fileObj
        except Exception as err:
            self.gMyAbort = True
            self.logger.exception(err.args[0])
            if MyMode == 1 :
                self.gMyAbort = True
                self.Cons80()
                self.Console("Could not open file : {0}".format(MyFile))
                self.Console(" due to : {0} :".format(err.args[0]) )                

                if MyText is None :
                    MyText = inspect.stack()[1][3]

                self.Console("Calling Routine:" + str(MyText))
                self.Console("Exiting ..." + self.DatetimeNow)
                self.Cons80()
            raise

        
    #Opens: None, Testing is completed
    def GetFileDLM(self, myFile, mode="I"):
        """
        '============================================
        'Return the delimiter to use based on the
        'file extension. Use \t for .tab, "|" for .asc
        'and "," for .csv or otherwise
        '
        '(input) :
        '----
        '1.) myFile: File to check
        'Note: the va script method has myMode, which has been deprecated
        '2.) mode : indicator if file in input (I) or output (O)
        '(output):
        '-------
        '1.) Delimiter. E.g., \t, "," or "|" or ""
        '============================================
        """
        if myFile is None:
            raise Exception("FileName: '{0}' is invalid".format(myFile))
        # add future delimiters to below dictionary
        fileDLMS = {('.tab', '.hive-tab','.hive-sequence') :   '\t'
                    ,('.asc')       :   '|'
                    ,('.txt')       :   ',' if mode=="I" else "" #can be removed
                    ,('.plus')      :   '+' 
                    }
        fileExtWithoutDelimeter = ['.sdb', '.json', '.pmpk']
        fileDLM = ','
        fileName, fileExt = os.path.splitext(myFile)
        self.logger.info("FileName = {0}, FileExt = {1}, mode = {2}".format(fileName, fileExt, mode))
        if self.IsEmptyOrNone(fileExt) is False and fileExt.lower() in fileExtWithoutDelimeter:
            errMsg = "File extension not supported to have a Delimiter: {0}".format(myFile)
            raise Exception(errMsg)

        #file extension is supported -- continue
        if self.IsEmptyOrNone(fileExt) is False:
            for key1, val1 in fileDLMS.items():
                if (fileExt.lower() in key1): 
                    fileDLM =  val1
                    break

        self.logger.info("For file: {0} Delimiter: {1}".format(myFile, fileDLM.encode("unicode-escape").decode()))
        return fileDLM

