    def Verify_Role2(self, MyUserF, MyRole, MyLocal) :
        """
        '============================
        'Verify users belong to Role
        '
        '(input) :
        '----
        '1.) MyUserF (StringType)   : Delimited File w/ hdr & list of email names, domains, idsids, 1 name per line
        '2.) MyRole (StringType)    : Role to chk
        '3.) MyLocal (StringType)   : Exe dir or N for SH...
        '
        '(output) :
        '----
        '1.) Verify_Role2_Out (BooleanType) : True if user(s) has access else False
        'GLOBALS:
        '-------
        'gSHFolder: SH Folder
        'gSPFLib  : Fixed ATTD SPF Library
        '=============================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        assert type(MyUserF) is str, "MyUserF input parameter is not a string : {0}".format(MyUserF)
        assert type(MyRole) is str, "MyRole input parameter is not a string : {0}".format(MyRole)
        assert type(MyLocal) is str, "MyLocal input parameter is not a string : {0}".format(MyLocal)

        #check if any argument is missing i.e., empty
        missingArgsErrMsg = "Input argument missing {0) : {1} ...Exiting..."
        assert (self.IsEmptyOrNone(MyUserF) is False), missingArgsErrMsg.format("User file" , MyUserF)
        assert (self.IsEmptyOrNone(MyRole) is False), missingArgsErrMsg.format("Role to Check" , MyRole)

        #Locals
        MyExe = ""
        myExePath = ""
        Verify_Role2_Out = False #(default)
        #constants
        EXE_TO_EXECUTE = "VerifyRole.exe"

        if self.SHisSHEntry : #'SH
            myExePath = self.gTempDir
            self.logger.debug("isSHEntry ")
        elif MyLocal == "N" :
            myExePath = gSPFLib + "library\\"
            self.logger.debug("MyLocal is N ")
        else :
            myExePath = MyLocal.strip()
            self.logger.debug("MyLocal is not N ")
        MyExe = os.path.join(myExePath, EXE_TO_EXECUTE)
        self.logger.debug("MyExe : {0}".format(MyExe))

        if MyUserF.strip().upper() != "ME" :
            if os.path.exists(MyUserF) == False:
                errMsg = "Could not locate file with User list: " + MyUserF
                raise IOError(errMsg)

        MyExe_call_args = [MyExe,"/role={0}".format(MyRole) ,"/infile={0}".format(MyUserF)]
        self.logger.debug("MyExe_call_args : {0}".format(MyExe_call_args))

        try :
            self.Console("  Verifying User list against Rialto Role(s): {0} ... {1}".format(MyRole, self.DatetimeNow))
            output_Data = subprocess.check_output(MyExe_call_args)
            self.logger.debug("subprocess.check_output.output : {0}".format(output_Data.decode()))
            Verify_Role2_Out = True
        except subprocess.CalledProcessError as err:
            self.logger.exception(err)
            self.logger.warn("cmd: {0}".format(err.cmd))
            self.logger.warn("args: {0}".format(err.args))
            self.logger.warn("returncode:{0}".format(err.returncode))
            self.Console(err.output.decode())            
        except Exception as err:
            self.logger.exception(err)
            pass #need not raise error

        #return the output
        self.logger.debug("Verify_Role2_Out : {0}".format(Verify_Role2_Out))   
        return Verify_Role2_Out   
    #END : def Verify_Role2

    #below method is replaced with re.sub...due to 'caseSenstive' handling bottleneck
    def replace_from_last(self, inputString, stringToReplace, replaceWith):
        if inputString.rfind(stringToReplace) > 0:
            beforeStringToReplace, _ ,afterStringToReplace = inputString.rpartition(stringToReplace)
            return beforeStringToReplace + replaceWith + afterStringToReplace
        else :
            return inputString
    #END : def replace_from_last

    # status : dev WIP
    def SPFRoboCopy(self, MyLocal, MyInstance, MyFile, MySrc, MyDest, MyRetry, MyWait, MyOpen, MyArg, MyErrOp, MyPassExitCodes=[]) :
        """
        '====================================================
        'Robocopy File
        '
        'Args:
        '====
        'MyLocal: Local Exe Dir or N or ...
        'MyFile : File to copy
        'MySrc  ; Source Dir
        'MyDest : Dest Dir
        'MyRetry: # retries
        'MyWait : Wait time between retries
        'MyOpen : Y to not copy if src file open
        'MyArg  : Addnal Robocopy args. E.g., /MOV
        'MyErrOp: Y=Abort if Src File ~found
        'MyPassExitCodes : List of exit codes that shall be treated as Pass exit codes E.g., : [13, 14, 15]
        '
        'GLOBALS:
        '-------
        'gLocalDir: Local Folder
        'gMyAbort :Job Abort global
        '====================================================
        """

        self.ConsoleWithTimeStamp("Starting Robocopy Applet, v1.6") #VA30.86
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        SPFRoboCopyStatus = False # assume robocopy failed
        MyData = None
        lMyArrRC = None
        i = None
        Tmp = None
        MyModStr = None
        TmpD = None
        MyDModStr = None
        SPFRoboCopyExitCode = {16 : "***Robocopy Fatal Error. No files copied***",
                                15 : "Robocopy OKCOPY + FAIL + MISMATCHES + XTRA",
                                14 : "Robocopy FAIL + MISMATCHES + XTRA",
                                13 : "Robocopy OKCOPY + FAIL + MISMATCHES",
                                12 : "Robocopy FAIL + MISMATCHES",
                                11 : "Robocopy OKCOPY + FAIL + XTRA",
                                10 : "Robocopy FAIL + XTRA",
                                9 : "Robocopy OKCOPY + FAIL",
                                8 : "Robocopy error. Some files/folders could not be copied",
                                7 : "Robocopy OKCOPY + MISMATCHES + XTRA",
                                6 : "Robocopy MISMATCHES + XTRA",
                                5 : "Robocopy OKCOPY + MISMATCHES",
                                4 : "Robocopy Mismatched files and folders detected",
                                3 : "Robocopy OKCOPY + XTRA",
                                2 : "Robocopy Extra files/folders detected",
                                1 : "Robocopy Successful (1)",
                                0 : "Robocopy Successful (0) No files need be copied"}

        SPFRoboCopy_pass_ExitCode = [0, 1, 2, 3]
        SPFRoboCopy_err_ExitCode = [item for item in SPFRoboCopyExitCode.keys() if item not in SPFRoboCopy_pass_ExitCode]

        self.logger.debug("{0} - MyLocal: '{1}'".format(calling_func, MyLocal))
        self.logger.debug("{0} - MyInstance: '{1}'".format(calling_func, MyInstance))
        self.logger.debug("{0} - MyFile: '{1}'".format(calling_func, MyFile))
        self.logger.debug("{0} - MySrc: '{1}'".format(calling_func, MySrc))
        self.logger.debug("{0} - MyDest: '{1}'".format(calling_func, MyDest))
        self.logger.debug("{0} - MyRetry: '{1}'".format(calling_func, MyRetry))
        self.logger.debug("{0} - MyWait: '{1}'".format(calling_func, MyWait))
        self.logger.debug("{0} - MyOpen: '{1}'".format(calling_func, MyOpen))
        self.logger.debug("{0} - MyArg: '{1}'".format(calling_func, MyArg))
        self.logger.debug("{0} - MyErrOp: '{1}'".format(calling_func, MyErrOp))
        self.logger.debug("{0} - MyPassExitCodes: '{1}'".format(calling_func, MyPassExitCodes))
        MySrc = MySrc.strip().rstrip("\\") if MySrc is not None else ""
        MyDest = MyDest.strip().rstrip("\\") if MyDest is not None else ""
        MyWait = 30 if MyWait is None else MyWait
        MyFile = MyFile.strip() if MyFile is not None else ""
        MyRetry = 100 if MyRetry is None else MyRetry
        MyOpen = MyOpen.strip().upper() if MyOpen is not None else ""
        MyArg = MyArg.strip().upper() if MyArg is not None else ""
        MyErrOp = MyErrOp.strip().upper() if MyErrOp is not None else ""

        if type(MyPassExitCodes) is not list:
            errMsg = "MyPassExitCodes should be a list of Exit Codes(numbers) E.g., [13, 14, 15] "
            raise Exception(errMsg)
        else:
            SPFRoboCopy_pass_ExitCode = SPFRoboCopy_pass_ExitCode + MyPassExitCodes
            self.logger.debug("{0} - updated : SPFRoboCopy_pass_ExitCode: '{1}'".format(calling_func, SPFRoboCopy_pass_ExitCode))


        if len(MyFile) == 0 :
            self.Console("  No Files specified to copy. Exiting ...")
        elif len(MySrc) == 0 :
            self.Console("  No Source Path specified. Exiting ...")
        elif len(MyDest) == 0 :
            self.Console("  No Destination Path specified. Exiting ...")
        #elif os.path.isdir(MySrc) == False :
        #'===v30.59  ===========  
        elif self.SHisSHEntry is False and  os.path.isdir(MySrc) is False : #' Folder ~exist for Interactive runs as SH may have network issues which robocopy will retry for
            self.Console("  Source path not found ({0}). Exiting ...".format(MySrc)) 
            self.gMyAbort = True
        else : 
            if MyOpen != "Y" : MyOpen = "N"
            if MyErrOp != "Y" : MyErrOp = "N"
            if MySrc in ["\\", ".\\"] : MySrc = "."
            if MyDest in ["\\", ".\\"] : MyDest = "."

            #print MyRetry.isdigit()
            try :
                MyRetry = int(MyRetry)
                MyWait = int(MyWait)
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    
            if type(MyRetry) != int:
                self.Console("  Retry Argument must be numeric ({0}). Exiting ...".format(MyRetry))
            elif type(MyWait) != int:
                self.Console("  Wait Argument must be numeric ({0}). Exiting ...".format(MyWait))
            elif MySrc == MyDest :
                self.Console("  Source and Destination folders are the same ({0}). Exiting ...{0}".format(MySrc))
            else : #proceed
                if MyFile.find("*") != -1 or MyFile.find(",") != -1 :
                    if MyOpen == "Y" or MyErrOp == "Y" :
                        self.Console("Sorry but neither the Open test nor the Abort if source file not found test can be done if wildcards are used or multiple files are to be copied")
                        MyOpen = "N"

                if MyOpen == "Y" or MyErrOp == "Y" :
                    Tmp = TmpD = MyFile
                    
                    if MySrc != "." :
                        Tmp = os.path.join(MySrc, Tmp) #MySrc + "\\" + Tmp
                    if MyDest != "." :
                        TmpD = os.path.join(MyDest, TmpD) #MyDest + "\\" + TmpD
                    
                    file_Exists_Retry, MyModStr = self.File_Exists_Retry(Tmp, MyErrOp)
                    
                    if file_Exists_Retry is False :
                        #self.Console("  Source File does not exist : {0}".format(Tmp))
                        errMsg = "  Source File does not exist : {0}".format(Tmp)
                        if MyErrOp == "Y" :
                            errMsg = "{0}\n  RoboCopy will exit with an error...".format(errMsg)
                            self.gMyAbort = True
                            raise Exception(errMsg)
                        else :
                            self.Console("  Copy will be skipped ...")
                            return #exit sub
                    elif MyOpen == "Y" :
                        #if self.FileIsLocked(Tmp) is True :
                        #    errMsg = "   Source File is currently open : {0}\n   RoboCopy will exit with an error...".format(Tmp)
                        #    self.gMyAbort = True
                        #    raise Exception(errMsg) #return #exit Sub   
                        fileRetry = True
                        maxFileRetryCount = 5 #100
                        myFileRetryCount = 0
                        fileRetrySleep = 15#30 #seconds
                        isMyFileLocked= False
                        while fileRetry is True:
                            isMyFileLocked = self.FileIsLocked(Tmp) 
                            if isMyFileLocked == True:
                                myFileRetryCount = myFileRetryCount + 1
                                if myFileRetryCount > maxFileRetryCount :
                                    fileRetry = False
                                    self.Console("      File appears locked even after {0} retries".format(maxFileRetryCount))
                                else:
                                    self.Console("      File appears locked ... Retry {0} ... {1}".format(myFileRetryCount, self.DatetimeNow))
                                    time.sleep(fileRetrySleep) 
                            else:
                                fileRetry = False                                         
                        #END : while fileRetry == True
                        if isMyFileLocked == True:
                            errMsg = "   Source File is currently open : {0}\n   RoboCopy will exit with an error...".format(Tmp)
                            self.gMyAbort = True
                            raise Exception(errMsg) #return #exit Sub
                    #end : if + elif : file_Exists_Retry == False :

                #End : if MyOpen == "Y" or MyErrOp == "Y" :
                
                lMyArrRC = MyFile.replace('"','').strip().split(",")
                del MyFile #no longer need this 

                self.logger.debug("Before clean up MyFilesArry -lMyArrRC : {0}".format(lMyArrRC))
                #remove empty items
                #'space is dlm. " = !!!
                lMyArrRC = ['"{0}"'.format(item.strip()) for item in lMyArrRC if self.IsEmptyOrNone(item) is False]

                self.logger.debug("After clean up MyFilesArry - lMyArrRC :{0}".format(lMyArrRC))

                if len(lMyArrRC) == 0 :
                    self.Console("  No Files specified to copy. Exiting ...")
                else :
                    #run command
                    myCMDToExecute = "ROBOCOPY"

                    myCMDArgs = ['"{0}"'.format(MySrc), 
                                 '"{0}"'.format(MyDest)] + lMyArrRC + ['/R:{0}'.format(MyRetry),
                                 '/W:{0}'.format(MyWait)] 
                                                            #'/W:{0}'.format(MyWait),
                                                            #"/NP",
                                                            #"/IS"]

                    if MyArg is not None and len(MyArg.strip()) != 0 :
                        if type(MyArg) is str: # types.StringType :
                            MyArg = MyArg.split(' ')
                        myCMDArgs = myCMDArgs + MyArg

                    self.logger.debug(myCMDToExecute)
                    self.logger.debug(myCMDArgs)
                    runVal, runExitCode = False, -1
                    try :
                      runVal, runExitCode =  self.Run(myCMDToExecute, myCMDArgs, SPFRoboCopy_pass_ExitCode, CMDErrorExitCodes=SPFRoboCopy_err_ExitCode,usePopen=True)
                    except Exception as err:
                        self.logger.exception("Error : {0}".format(err))
                        runVal = err.args[2]
                        runExitCode = err.args[1]
                        #raise

                    self.Console("{0} - ExitCode : {1} ".format(SPFRoboCopyExitCode[runExitCode], runExitCode))
                    if runVal is False :
                        errMsg = "   RoboCopy considered unsuccessful..."
                        self.gMyAbort = True
                        raise Exception(errMsg)
                    elif MyErrOp == "Y" :
                        MyDModStr = self.GetFileDate(TmpD)
                        self.logger.debug("{0} - MyDModStr: '{1}'".format(calling_func, MyDModStr))
                        #if MyModStr != MyDModStr : '===== v30.86 ========== -- replace with below line
                        if str(MyDModStr).find("1980-01-01") > -1 or MyDModStr == -1: 
                            errMsg = ("   Source and Destination File Dates do not match..."
                                      "\n     Source     = {MyModStr}"
                                      "\n     Destination= {MyDModStr}"
                                      "\n   RoboCopy considered unsuccessful...").format(MyModStr=MyModStr, MyDModStr=MyDModStr)
                            self.gMyAbort = True
                            raise Exception(errMsg)
                        else :
                            #self.Console("   Source and Destination File Dates Match: %s" % str(MyModStr))#'===== v30.86 ========== -- replaced with below line
                            self.Console("   Acceptable Destination (and source) File Dates: {MyDModStr} ({MyModStr})".format(MyDModStr=MyDModStr, MyModStr=MyModStr))
                            SPFRoboCopyStatus = True
                    else :
                        SPFRoboCopyStatus = True
                self.ConsoleDoneWithoutTimeStamp()
            #end : else : #proceed
            return SPFRoboCopyStatus
    #end : def SPFRoboCopy

    # status : dev done UT done
    def File_Exists_Retry(self, MyFile, MyMode, MyRetry = 3, MySecs = 30, showConsoleMsgs=True) :
        """
        '===========================================
        'Test if file exists. Retry in case of netwk
        'issues. Return 1 if found, else 0
        '
        'INPUT :
        '-----------
        ' 1.) MyFile : StringType : 
            File to test
        ' 2.) MyMode : StringType : 
            Y to also return File Mod Date
        ' 3.) MyRetry : IntType : Retry counter default = 3
        ' 4.) MySecs : IntType : Sleep time default = 30 seconds
        'OUTPUT : (multiple) :  
        '---------------------
        ' 1.) retVal : BooleanType :
                'True' if File exists
        ' 2.) MyModStr : StringType : 
                '2014-Apr-14 19:41:21' File Mod Date if file found
        '===========================================
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        if showConsoleMsgs : self.Console("Testing if file exists: {0}".format(MyFile))
        retVal = False #file doesn't exist
        Ctr = 0
         #'seconds
        MyModStr = None

        while (Ctr <= MyRetry and retVal == False) :
            
            if os.path.exists(MyFile) :
                retVal = True
                if MyMode == "Y" :
                    MyModStr = self.GetFileDate(MyFile)
                if showConsoleMsgs : self.Console("    Found ...")
            else :
                self.Console("  Retry : " + str(Ctr+1) + "...")
                if Ctr < MyRetry :
                    time.sleep(MySecs)
                Ctr = Ctr + 1
        #end of While
        self.logger.debug("{0} - File_Exists_Retry : {1}".format(calling_func, retVal))
        self.logger.debug("{0} - MyModStr : {1}".format(calling_func, MyModStr))
        return retVal, MyModStr
    #END : def File_Exists_Retry

    #status : Dev done UT Done
    def GetFileDate(self, MyFileN) :
        """
        '===================
        'Get File Mod Date + with retry
        '
        'ARGS:
        '----
        'MyFileN :File Path
        '===================
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        retVal = -1
        self.logger.debug("{0} - MyFileN : {1}".format(calling_func, MyFileN))        
        MyRetryAttempts = range(1,6)
        MyWait= 30 #seconds
        
        for attempt in MyRetryAttempts: 
            self.Console("  Get File Date Retry - {0}".format(attempt))
            if os.path.exists(MyFileN):
                try:
                    retVal = time.strftime(self.G_DT_FORMAT_YYYY_MM_DD_HH24_MM_SS,
                                            time.strptime(time.ctime(os.path.getmtime(MyFileN))))
                    break
                except Exception as err:
                    self.Console("  Error getting File Date: {0}".format(err))
                    time.sleep(MyWait)
            else:
                self.Console("  File Not Yet Found: {0}".format(MyFileN))
                time.sleep(MyWait)
        self.logger.debug("{0} - GetFileDate : {1}".format(calling_func, retVal))
        return retVal
    #END : def GetFileDate

    #status : dev done, UT done
    def FileIsLocked(self, MyFile):
        """
        #checks if MyFile exists and if it is locked
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        retVal = True #is locked
        buffer_size = 8
        self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
        try : 
            if os.path.exists(MyFile):
                isreadonly=False
                try :
                    attrs = win32api.GetFileAttributes(MyFile)
                    isreadonly=attrs & win32con.FILE_ATTRIBUTE_READONLY #1=True and 0 = False
                except Exception as err: 
                    pass
                if isreadonly:
                    retVal=False
                else:
                    with open(MyFile, "ab", buffer_size) as file_object: #read in binary mode in both Python 2.x & 3.x..no encoding required in binary mode
                        pass # do nothing...if file is locked it will fail to open and err is raised
                    retVal = False #passed...is not locked
            else:
                retVal = False # file doesn't exist
        except Exception as err:
            self.logger.exception("{0} - Failed to access file : {1}".format(calling_func, MyFile))

        self.logger.debug("{0} - FileIsLocked : {1}".format(calling_func, retVal))
        return retVal

    #status : dev done, UT WIP
    def File_Lock_Move(self, srcFile, DstFile):
        """
        '===========================
        'Move File. If Locked, retry
        '
        'INPUT ARGS:
        '-----
        'SrcFile : Src File
        'DstFile : Dst File
        ' 
        'ON ERROR:
        ' raise error
        '============================
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        File_Lock_Move_Status = True #is locked
        maxRetryCount = 5 #100
        myRetryCount = 1
        retrySleep = 30 #seconds

        self.logger.debug("{0} - srcFile : {1}".format(calling_func, srcFile))
        self.logger.debug("{0} - DstFile : {1}".format(calling_func, DstFile))
        self.logger.debug("{0} - os.path.exists(DstFile) : {1}".format(calling_func, os.path.exists(DstFile)))
        try :
            self.ConsoleWithTimeStampNoLF("  Preparing to Rename") 
            if os.path.exists(DstFile) : 
                self.logger.debug("{0} - DstFile exists : {1}".format(calling_func, os.path.exists(DstFile)))
                
            retry = True
            while retry is True :
                try:
                    if self.FileIsLocked(DstFile) is True:
                        #self.Console("      Dest. File locked ... Retry {0} ... {1}".format(myRetryCount, self.DatetimeNow))
                        errMsg = "      Dest. File locked ... Retry {0} ... {1}".format(myRetryCount, self.DatetimeNow)
                        finalErrMsg = "      File is locked even after {0} retries".format(maxRetryCount)
                        raise Exception(errMsg)
                    else :
                        self.Console("     Renaming ... {0}".format(self.DatetimeNow))
                        cmdToExecute = "%COMSPEC%"
                        cmdArgs = ['/c', 'move', '/Y', '"{0}"'.format(srcFile), '"{0}"'.format(DstFile)]
                        try:
                            File_Lock_Move_Status, runExitCode = self.Run(cmdToExecute, cmdArgs)
                        except SPFCMDRunExitWithErrorCodeException as SPFCmdExErr:
                            errMsg = ("      Error during move "
                                      "\n      srcFile : {0}" 
                                      "\n      to "
                                      "\n      DstFile : {1} file. "
                                      "\n      ... Retry {2} ... {3}").format(srcFile, DstFile, myRetryCount, self.DatetimeNow)
                            finalErrMsg = ("      Error during move "
                                           "\n      srcFile : {0}" 
                                           "\n      to "
                                           "\n      DstFile : {1} file. "
                                           "\n      Even after {2} retries").format(srcFile, DstFile, myRetryCount, self.DatetimeNow)
                            #"Error during move srcFile : {0} to DstFile : {1} file. even after {2} retries".format(srcFile, DstFile, maxRetryCount)
                            raise Exception(errMsg)
                    self.Console("     Renamed ... {0}".format(self.DatetimeNow))
                    retry = False
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    
                    myRetryCount = myRetryCount + 1
                    time.sleep(retrySleep)
                    if myRetryCount > maxRetryCount :
                        retry = False
                        #errMsg = "File is locked even after {0} retries"
                        self.ConsoleWithCons80(finalErrMsg)
                        raise Exception(finalErrMsg)
                    self.ConsoleWithCons80(err.args[0])
                    
            #END : while retry == True
            

        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise 

    #Status: Dev Done, UT Done
    def Run(self, CMDToExecute, CMDArguments, CMDPassExitCodes=[0], CMDErrOutputFileName = None, 
            CheckOutputHasErrorTxt=False, CMDErrorExitCodes=[-1, -2, 1, 2], usePopen=False, nonBlocking=False) : 
        """
        'execute given application/console command and return/write to output file
        'Mimics VA utilities.run method.  
        ' INPUT :
        '--------
        ' 1.) CMDToExecute : StringType :
                Command that needs to be executed E.g.: "ROBOCOPY"
        ' 2.) CMDArguments : ListType :
                List of required arguments that need to be passed to the command to execute
        ' 3.) CMDPassExitCodes : ListType :
                List of Exit codes that indicate Run is a success
        ' 4.) CMDErrOutputFileName : StringType : None
                File to which 'ERROR' needs to be written        
                Open : This can be dropped?
        ' 5.) CheckOutputHasErrorTxt : Bool : False
                Flag to indicate if output should be checked for error Text
        ' 6.) CMDErrorExitCodes : List : [-1, -2, 1, 2]
                List of exit codes which indicate failure
        ' 7.) usePopen : Bool : False
                Flag to indicate if subprocess.popen should be used (this is mainly to address output getting messed up in SH environment)
                Note: Not all calls need this. Few functions like Run_R, etc need this to properly output to log file (SH)
        ' 8.) nonBlocking : Bool : False
                Flag to indicate if the command needs to be executed in Asyn(True) or not (False)
        '
        ' Output : (multiple) : 
        '----------------------
        ' 1.) runStatus : BooleanType : True = Passed & False = Failed
        ' 2.) runExitCode : IntegerType : value returned by the called external app/cmd
        '
        ' On Error : (err args to be read by caller)
        '-----------------------
        ' [0] : CMDExecuted : StringType : command + all arguments that were passed popen
        ' [1] : runExitCode : IntegerType : value returned by the called external app/cmd
        ' [2] : runStatus : BooleanType : True = Passed & False = Failed
        '
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY       Author      Description
        '   ----        -----       ------      -----------
        '   1.0         WW27'15     Nataraj     Initial Version using subprocess.checkoutput.
        '   1.1         WW28'15     Nataraj     Moved to subprocess.popen with proper console output for long running operations.
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        runStatus = True # assume execution pass
        runExitCode = -1 # Exit code from subprocess
        runOutput = "" # capture the output from subprocess

        try :
            self.logger.debug("{0} - CMDToExecute : {1}".format(calling_func, CMDToExecute))
            self.logger.debug("{0} - CMDArguments : {1}".format(calling_func, self.maskSensitiveInfo(CMDArguments)))
            self.logger.debug("{0} - CMDPassExitCodes : {1}".format(calling_func, CMDPassExitCodes))
            self.logger.debug("{0} - CMDErrOutputFileName : {1}".format(calling_func, CMDErrOutputFileName))
            self.logger.debug("{0} - CheckOutputHasErrorTxt : {1}".format(calling_func, CheckOutputHasErrorTxt))
            self.logger.debug("{0} - CMDErrorExitCodes : {1}".format(calling_func, CMDErrorExitCodes))
            self.logger.debug("{0} - usePopen : {1}".format(calling_func, usePopen))
            self.logger.debug("{0} - nonBlocking : {1}".format(calling_func, nonBlocking))

            if self.gIsSvc is True:
                usePopen = True
                self.logger.debug("{0} - usePopen : {1}; gIsSvc : {2}".format(calling_func, usePopen, self.gIsSvc))

            #SubProcArguments = ['"{0}"'.format(CMDToExecute)]
            SubProcArguments = [CMDToExecute if CMDToExecute.find(" ") == -1 or (CMDToExecute[0] == '"' and CMDToExecute[-1] == '"') else '"{0}"'.format(CMDToExecute.strip('"'))]
            self.logger.debug("{0} - SubProcArguments : {1}".format(calling_func, self.maskSensitiveInfo(SubProcArguments)))
            #CMDArguments = [item1 if item1.strip().find(" ") == -1 else '"{0}"'.format(item1.strip('"')) for item1 in CMDArguments]
            #self.logger.debug("{0} - CMDArguments : {1}".format(calling_func, self.maskSensitiveInfo(CMDArguments)))
            SubProcArguments = SubProcArguments + CMDArguments 
            #SubProcArguments = [item1 if item1.find(" ") == -1 else '"{0}"'.format(item1.strip()) for item1 in SubProcArguments]

            #self.logger.debug("{0} - SubProcArguments : {1}".format(calling_func, self.maskSensitiveInfo(SubProcArguments)))

            #start the execution
            SubProcArgumentsStr = " ".join(SubProcArguments) #issue if list is passed to subprocess.Popen...if value is a path and when calling a dotNet app
            self.logger.debug("{0} - SubProcArgumentsStr : {1}".format(calling_func, self.maskSensitiveInfo(SubProcArgumentsStr)))
            if usePopen is False : #and self.SHisSHEntry is False:
                runExitCode = subprocess.call(SubProcArgumentsStr, shell=True)
            else : #some console commands mess up output when logged to a file...so use below E.g., DOS commands like Echo, etc
                myProcess = subprocess.Popen(SubProcArgumentsStr, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE, shell=True)
                if nonBlocking is True: #E.g., need to run a DOS 'START' command
                    return True, 0
                #read and print to stdout (console)
                while True : 
                    #nextVal = myProcess.stdout.read(1)
                    try :
                        nextVal, errVal = myProcess.communicate()
                        if isPYTHON2 is False: #Pyhton 3 : returns bytes -- convert to str
                            nextVal, errVal = nextVal.decode(), errVal.decode()
                        self.Console(nextVal.replace("\r", ""))
                        if self.IsEmptyOrNone(errVal) is False :
                            self.Console(errVal.replace("\r", ""))
                            runOutput = runOutput + errVal
                        #store the output for logging
                        runOutput = runOutput + nextVal
                        #print("nextVal : {0}\nerrVal : {1}\nmyProcess.poll() : {2}".format(nextVal, errVal, myProcess.poll()))
                        #if (self.IsEmptyOrNone(nextVal) is True and self.IsEmptyOrNone(errVal) is True) or myProcess.poll() is not None :
                        if myProcess.poll() is not None:
                            break

                    except ValueError as valErr :
                        self.logger.exception(vallErr)
                    except Exception as err1 :
                        self.logger.exception(err1)
                        raise
                #END while True : 
                self.logger.debug("{0} - subprocess.output : {1}".format(calling_func, runOutput))
                ##get return code
                runExitCode = myProcess.returncode
            #END : if usePopen is False :     
            
            self.logger.debug("{0} - runExitCode : {1}".format(calling_func, runExitCode))
            
            self.logger.debug("{0} - completed execution".format(calling_func))

            if CheckOutputHasErrorTxt is True and runExitCode not in CMDErrorExitCodes:
                #the DotNet external apps return 0 even on error...need to check output if 'error' text is present
                if bool(re.search("error", runOutput,re.IGNORECASE)) == True :
                    self.logger.debug("{0} - found error in output setting runStatus as failure".format(calling_func))
                    runExitCode = 1
                    runStatus = False

            if runExitCode not in CMDPassExitCodes and runExitCode in CMDErrorExitCodes:
                cmdExecuted = " ".join(self.maskSensitiveInfo(SubProcArguments))
                runStatus = False

                if self.IsEmptyOrNone(CMDErrOutputFileName) is False:
                    try :
                        with open(CMDErrOutputFileName, 'w') as errFile: #no need to handle for Python 3.x...just writing simple text
                            errFile.write("ERROR")
                    except Exception as err:
                        errMsg = "Error while writing 'ERROR' to : {0}".format(CMDErrOutputFileName)
                        self.logger.exception(errMsg)
                #END if CMDErrOutputFileName is not None :

                raise SPFCMDRunExitWithErrorCodeException(cmdExecuted, runExitCode, runStatus)
            #END if runExitCode != 0 :

            #runStatus = True # execution passed
        except WindowsError as winErr :
            self.logger.exception("{0} - WinError in Run - {1}".format(calling_func, winErr.strerror))
            raise Exception(winErr.strerror)
        except Exception as err :
            self.logger.exception("{0} - Error in Run - {1}".format(calling_func, err.args[0]))
            raise
        return runStatus, runExitCode

    #status : dev done. UT Done(using CL_xx)
    def Substitute_Global_Var(self, myDataToScanReplace):
        """
        '====================
        'Subst. Global Vars
        '
        'INPUT ARG:
        '----------
        ' 1.) myDataToScanReplace : StringType : Data that needs to be scanned and replace with correct values
        '
        'OUTPUT (single) :
        '-----------------
        ' 1.) myDataToScanReplace : StringType : updated value
        '
        ' ON ERROR :
        '-----------
        ' 1.) raise error
        '
        'GLOBALS:
        '-------
        'gMySPFJobDay:SPF Job Start Day
        'gMySPFGWDT  :Job Start GMT time
        'gSPFVaryLib :Exe/Lib Dir
        'g_gVars : Multi {} array of CL_ Globals
        ' NOT USED : 
        'g_VarNo : # CL_ Globals - 1 passed in as args : this is no longer needed in py
        '
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW29.4'15       Nataraj     Initial Version
        '   1.1         WW30.1'15       Nataraj     Added g_gVars handling
        '   1.2         WW30.3'15       Nataraj     Added calling of substitute_env
        '   1.3         WW42.6'16       Nataraj     VA30_47: changes
        '   1.4         WW45.2'19       Nataraj     Update filepath substitution to use os.path.join
        '======================================================

        '====================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)

        # Dictionary to scan for on key and replace with value
        # add any new items to below dict
        scanForDict = collections.OrderedDict()
        scanForDict[r"<<<spf-job-start-day>>>"] = self.gMySPFJobDay
        scanForDict[r"<<<spf-job-start-gmt-time>>>"] = self.gMySPFGWDT
        scanForDict[r"<<<spf-job-start-time>>>"] = self.gMySPFJobDT #VA30_47

        #Dictionary to for handling filepath global variables
        scanForDict_filePathVars = collections.OrderedDict()
        scanForDict_filePathVars[r"<<<spf-default-dir>>>"] = self.gLocalDir
        scanForDict_filePathVars[r"<<<spf-default-exe>>>"] = self.gSPFVaryLib
        scanForDict_filePathVars[r"<<<spf-default-exe2>>>"] = self.gSPFExe

        #add any gVars : CL_xxx items 
        for gVarItemKey, gVarItemValue in self.g_gVars.iteritems() if isPYTHON2 else self.g_gVars.items():
            scanForDict["<<<{0}>>>".format(gVarItemKey)] = gVarItemValue

        self.logger.debug("{0} - scanForDict = {1} ".format(calling_func, scanForDict))

        try :
            #self.logger.debug("{0} - {1}".format(calling_func, myDataToScanReplace))
            if myDataToScanReplace is None :
                raise Exception("Input is None")
            #now iterate the scanForDict
            for keyToScan, ValToReplace in scanForDict.iteritems()  if isPYTHON2 else scanForDict.items():
                #perform replace
                self.logger.debug("{0} - substituting '{1}' with '{2}'".format(calling_func, keyToScan, ValToReplace))
                myDataToScanReplace = re.sub(keyToScan, lambda x: ValToReplace, myDataToScanReplace, 0, re.IGNORECASE|re.MULTILINE)

            #now iterate the scanForDict_filePathVars -- for filePath variable. Note: this checks for ending path seperator in the path value
            for keyToScan, ValToReplace in scanForDict_filePathVars.iteritems()  if isPYTHON2 else scanForDict_filePathVars.items():
                #check if the path value ends with filepath seperator 
                ValToReplace = ValToReplace if ValToReplace.endswith(os.path.sep) is True else "{0}{1}".format(ValToReplace, os.path.sep)
                #perform replace
                self.logger.debug("{0} - substituting '{1}' with '{2}'".format(calling_func, keyToScan, ValToReplace))
                myDataToScanReplace = re.sub(keyToScan, lambda x: ValToReplace, myDataToScanReplace, 0, re.IGNORECASE|re.MULTILINE)                            
            #substitute env vars
            myDataToScanReplace = self.Substitute_Env(myDataToScanReplace)

            #return updated string
            self.logger.debug("{0} - Substitute Global_Var & Env completed : {1}".format(calling_func, self.strip_connection(myDataToScanReplace)))
            return myDataToScanReplace
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def Substitute_Global_Var

    #status : dev done, UT done
    def Substitute_Env(self, myDataToScanReplace) :
        """
        '====================================================
        'Substitutes Env't vars of form <<<%macro%>>>
        '
        'INPUT ARGS:
        '-----------
        ' 1.) myDataToScanReplace : StringType : string that needs to be scanned and replaced with correct Env't var value.
        '
        'OUTPUT : (single)
        '----------------
        ' 1.) myDataOut : StringType : formated output string With Env Vars Substituted
        '
        'ON ERROR : (no output)
        '----------
        ' 1.) raise exception
        '
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW29.4'15       Nataraj     Initial Version
        '======================================================
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)

        def CheckReplace_Env_Items(matchObj) :
            """
                A nested function of Substitute_Env. Perform check/replace logic.
            This function is called in regex sub function. 
            (input) :
            1. matchObj : macthed regex object (will contain the matched string and its subroups)
            (output) : 
            1. updated string value
            """
            if matchObj is not None :
                matcheValueFull = matchObj.group()
                self.logger.debug ("{0} - matcheValueFull : {1}".format(calling_func, matcheValueFull))
                #get the named tokens
                s_token_item = matchObj.group('S_TOKEN')
                env_var_item = matchObj.group('ENV')
                e_token_item = matchObj.group('E_TOKEN')

                #check if env_var_item is valid
                if len(env_var_item) == 0 :
                    raise Exception("Found invalid Environment variable name : {0} ".format(matcheValueFull))
                
                self.logger.debug("{0} - s_token_item {1}".format(calling_func, s_token_item))
                self.logger.debug("{0} - env_var_item {1}".format(calling_func, env_var_item))
                self.logger.debug("{0} - e_token_item {1}".format(calling_func, e_token_item))
                
                #get the environment variable value from system
                env_var_value = os.getenv(env_var_item)

                if env_var_value is None or len(env_var_value) == 0 :
                    raise Exception("Environment variable {0} not found".format(matcheValueFull))

                self.logger.debug("{0} - env_var_value {1}".format(calling_func, env_var_value))
                #return value which will get substituted in the string that is being searched
                return env_var_value
            #END : CheckReplace_Env_Items
        #Substitute_Env -- continue
        try :
            """
            regex patern : prep the pattern which needs to match
            """
            regexPatStr = r"""
                            (?P<S_TOKEN><<<\%)  # should begin with this  
                            (?P<ENV>[\s\w]*)    # get any alphanumeric 
                            (?P<E_TOKEN>\%>>>)  # should end with this
                            """
            #compile the regex
            regexPatern = re.compile(regexPatStr, re.VERBOSE|re.MULTILINE|re.IGNORECASE)

            self.logger.debug("{0} - myDataToScanReplace : {1}".format(calling_func, self.strip_connection(myDataToScanReplace)))

            """
            regex sub : for every pattern matched string substitue required value in func CheckReplace_Env_Items
            """
            myDataOut = regexPatern.sub(CheckReplace_Env_Items, myDataToScanReplace)
            self.logger.debug("{0} - myDataOut : {1}".format(calling_func,self.strip_connection(myDataOut)))

            #check if there are any wrong format left
            if myDataOut.find("<<<%") > -1 or myDataOut.find("%>>>") > -1 :
                raise Exception("Environment variables specified in wrong format. Correct format : '<<<%ENV_VARIABLE_NAME%>>>'" )

            #all checks passed...return
            return myDataOut

        except Exception as err:
            self.logger.exception("{0} - ".format(calling_func, err.args[0]))
            raise
    #END : def Substitute_Env

    #status : Dev done, UT done
    def setEnv(self, EnvVarName, EvnVarValue) : 
        """
        '====================================================
        'set Environment variables for this session
        '
        'INPUT ARGS:
        '-----------
        ' 1.) EnvVarName : StringType : Env't variable name.
        ' 2.) EvnVarValue : StringType : Env't variable Value. 
        '
        'OUTPUT : (single)
        '----------------
        ' 1.) setEnvStatus : BooleanType : True if Env't var was set ELSE False
        '
        'ON ERROR : (no output)
        '----------
        ' 1.) raise exception
        '
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW29.5'15       Nataraj     Initial Version
        '   1.1         WW11.4'20       Nataraj     Update console statement post createing environment variable
        '======================================================
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        
        setEnvStatus = True
        try :
            self.logger.debug("{0} - EnvVar Name : '{1}'; Value : '{2}'; valueType : '{3}' ".format(calling_func, EnvVarName, EvnVarValue, type(EvnVarValue)))

            os.environ[EnvVarName] = str(EvnVarValue)

            self.logger.debug("{0} - Env Var set : {1} = {2}".format(calling_func, EnvVarName, os.environ[EnvVarName]))

        except Exception as err:
            setEnvStatus = False
            self.logger.exception("{0} - ".format(calling_func, err.args[0]))
            raise

        return setEnvStatus

    #END : def setEnv

