    def Final_CleanUp(self, MyTmpFName) :
        """
        '====================================================
        'Clean up tmp files
        '
        'INPUT ARGS:
        '-----------
        ' 1.) MyTmpFName : StringType : Tmp File.
        '         '
        'OUTPUT : (single)
        '----------------
        ' 1.) Final_CleanUpStatus : BooleanType : True if clean up passed ELSE False
        '
        'ON ERROR : (no output)
        '----------
        ' 1.) log exception -- dont raise error
        '
        'GLOBALS:
        '---------
        ' 1.) gRunMode: IB=Packed Exe is run
        '
        'Dropped (input):
        '--------
        '1.) MyLocal : StringType : N=remote q. # -- this is now a global variable
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW30.2'15       Nataraj     Initial Version
        '======================================================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        
        Final_CleanUpStatus = True
        FilesToDelete = []
        FileToDeleteFound = []
        
        try :
            self.logger.debug("{0} - MyTmpFName : {1}".format(calling_func, MyTmpFName)) 
            FilesToDelete.append(os.path.join(".\\", MyTmpFName + ".txt"))
            FilesToDelete.append(os.path.join(".\\", MyTmpFName + ".bat"))
            
            if self.gMyLocal == "N" :
                if self.SHisSHEntry is False :
                    FilesToDelete.append(os.path.join(".\\", "record_spf.bat"))
                    FilesToDelete.append(os.path.join(".\\", "run_sqlplus.bat"))
                FilesToDelete.append(os.path.join(".\\", "unzip.exe"))
                FilesToDelete.append(os.path.join(".\\", "schema.ini"))

            #VA30_47 : changes add *_*.cols for deletion
            if self.gMyLocal == "N" or self.gRunMode == "IB" :
                FilesToDelete  = FilesToDelete + [os.path.join(".\\", fileItem) for fileItem in glob.glob("*_*.cols")]

            self.logger.debug("{0} - FilesToDelete : {1}".format(calling_func, FilesToDelete))

            
            for FileToDelete in FilesToDelete :
                if os.path.exists(FileToDelete) is True :
                    #os.remove(FileToDelete) # use this...?
                    FileToDeleteFound.append("&&Del")
                    FileToDeleteFound.append("/F")
                    FileToDeleteFound.append("/Q")
                    FileToDeleteFound.append(FileToDelete)
            
            if len(FileToDeleteFound) > 0 :
                cmdRunPassCodes = [0]
                cmdToRun = "%COMSPEC%" 
                cmdArgsList = ["/c", 'CD', '/d', self.gLocalDir] 
                cmdArgsList = cmdArgsList + FileToDeleteFound
                Final_CleanUpStatus, runExitCode = self.Run(cmdToRun, cmdArgsList, cmdRunPassCodes)
            else : 
                self.logger.debug("{0} - no files found to delete".format(calling_func))

            self.logger.debug("{0} - Final_CleanUpStatus: {1}".format(calling_func, Final_CleanUpStatus))
        
            return Final_CleanUpStatus

        except Exception as err:
            Final_CleanUpStatus = False
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
    #END : def Final_CleanUp

    #status : dev WIP
    def Substitute_Macro(self, myDataToScanReplace, parentMacTables, Rowidx, MyMode, currentRow=None) :
        """
        '====================================================
        'Substitute macro names of form <<<macro>>> or {macro} with hdrs from MEMTable
        'MacTbl in Data Row "RowIdx"
        '
        'INPUT ARGS:
        '-----------
        ' 1.) myDataToScanReplace : StringType : SPFSQL query.
        ' 2.) parentMacTables  : list of memtable Object or MacTbl item : Mem Tbl With Macro Name/Val xlations. If single MacTblItem a dict object is created and consumed
        ' 3.) Rowidx  : IntType : Row of Macro Mem Tbl Being processed
        ' 4.) MyMode  : IntType : 0=Look for vars bounded by <<< & >>>
        '        1=Look for vars bounded by { & } 
        ' 5.) currentRow : Row index currently being processed
        'OUTPUT : (single)
        '----------------
        '1.) myDataOut : StringType : Query With Macro Vars Substituted or an Error String
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW30.2'15       Nataraj     Initial Version
        '======================================================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - type(parentMacTables) : {1}".format(calling_func, type(parentMacTables)))
        
             
        MacTblRow = None
        MacTblIdx = 0

        def CheckReplace_Macro_Items(matchObj) : 
            """
                A nested function of Substitute_Macro. Perform check/replace logic.
            This function is called in regex sub function. 
            (input) :
            1. matchObj : macthed regex object (will contain the matched string and its subroups)
            (output) : 
            1. updated string value
            """
            if matchObj is not None :
                matcheValueFull = matchObj.group()
                self.logger.debug ("{0} - matcheValueFull : {1}".format(calling_func, matcheValueFull))
                #get the named tokens
                s_token_item = matchObj.group('S_TOKEN')
                macro_var_item = matchObj.group('MACRO').strip()
                e_token_item = matchObj.group('E_TOKEN')

                #check if macro_var_item is valid
                if len(macro_var_item) == 0 :
                    raise Exception("Found invalid macro variable name : {0} ".format(matcheValueFull))
                
                self.logger.debug("{0} - s_token_item : '{1}'".format(calling_func, s_token_item))
                self.logger.debug("{0} - macro_var_item : '{1}'".format(calling_func, macro_var_item))
                self.logger.debug("{0} - e_token_item : '{1}'".format(calling_func, e_token_item))
                
                macro_var_value = None
                if matcheValueFull == "<<<spf_datetime>>>" :  #note this is used in PyEE PMQ flow
                    #note: this is used in PyEE PMQ flow
                    return "<<<spf_datetime>>>"

                if re.search(r"<<<(spf(-|\$)|%|!)", matcheValueFull, re.IGNORECASE): 
                    #match anything starting like '<<<spf-' or '<<<spf$' or '<<<%' or '<<<!'
                    #'Ignore special macro variables or 'Ignore env't variables
                    return matcheValueFull

                try :
                    #get the macro variable value from memtable row
                    colIdx = [idx for idx, item in enumerate(MacTblCols) if re.search(r"^\[?{0}\]?$".format(macro_var_item.replace("|", "\\|")), item, re.IGNORECASE)][0]
                    self.logger.debug("{0} - colIdx {1}".format(calling_func, colIdx))
                    macro_var_value = str(MacTblRow[colIdx])
                    self.logger.debug("{0} - macro_var_value {1}".format(calling_func, macro_var_value))
                    #macro_var_value = MacTblRow[0]

                except Exception as err:
                    self.logger.info("{0} - inside MacTblIdx : {1}".format(calling_func, MacTblIdx))
                    self.logger.exception(err)
                    errMsg = "ERROR - Could not find Macro translation in Macro file for: {0}{1}{2}".format(s_token_item, macro_var_item, e_token_item)
                    #raise Exception(errMsg)
                    if len(parentMacTables) > 1 and MacTblIdx < len(parentMacTables)-1:
                        macro_var_value = matcheValueFull
                    else:
                        raise SPFMacroNotFoundException(errMsg)
                #region Ver: 1.1.0.1_VA30_90 : commented raise error when macro_var_value is None or empty...use empty value and if None use ''
                #if macro_var_value is None or len(macro_var_value) == 0 :
                #    raise Exception("Macro variable {0} not found".format(matcheValueFull))

                if macro_var_value is None: #Ver: 1.1.0.1_VA30_90 : commented above 
                    macro_var_value = ''
                #endregion Ver: 1.1.0.1_VA30_90

                self.logger.debug("{0} - macro_var_value {1}".format(calling_func, macro_var_value))
                #return value which will get substituted in the string that is being searched
                return macro_var_value


        try : 
            """
            regex patern : prep the pattern which needs to match
            """
            if MyMode == 1 :
                regexPatStr = r"""
                                (?P<S_TOKEN>\{)  # should begin with this  
                                (?P<MACRO>.*?)   
                                (?P<E_TOKEN>\})  # should end with this
                                """
                regexPatStrValidateEToken = r"(?P<S_TOKEN>{)(?P<MACRO>[\s\w\%\-]*)"

            elif MyMode == 0 :
                regexPatStr = """
                                (?P<S_TOKEN><<<)  # should begin with this  
                                (?P<MACRO>.*?)    
                                (?P<E_TOKEN>>>>)  # should end with this
                                """
                regexPatStrValidateEToken = r"(?P<S_TOKEN><<<)(?P<MACRO>[\s\w\%\-]*)"
            else :
                raise Exception("Invalid MyMode : {0}".format(MyMode))

            #compile the regex
            regexPatern = re.compile(regexPatStr, re.VERBOSE|re.MULTILINE|re.IGNORECASE)

            #self.logger.info("{0} - myDataToScanReplace : {1}".format(calling_func, myDataToScanReplace))
            #self.logger.info("{0} - Rowidx : {1}".format(calling_func, Rowidx))
            #self.logger.info("{0} - MyMode : {1}".format(calling_func, MyMode))
            #self.logger.info("{0} - MacTbl : {1}".format(calling_func, MacTbl))
            try:
                self.logger.info("{0} - parentMacTables : {1}".format(calling_func, parentMacTables))
                if type(parentMacTables) is not collections.OrderedDict:
                    parentMacTables = {'temp': parentMacTables}
                self.logger.info("{0} - len(parentMacTables) : {1}".format(calling_func, len(parentMacTables)))
                myDataOut =  myDataToScanReplace
                #for MacTblIdx, MacTblItem in enumerate(parentMacTables[::-1]):
                for MacTblIdx, MacTblItemKey in enumerate(list(parentMacTables.keys())[::-1]):
                    """
                    get memtable row for Rowidx
                    """
                    self.logger.info("{0} - starting processing MacTblIdx : {1} -- {2} ".format(calling_func, MacTblIdx, MacTblItemKey))
                    MacTblItem = parentMacTables[MacTblItemKey]
                    #self.logger.info("{0} - tables in MacTblItem : {1}".format(calling_func, MacTblItem.GetTablesInMemTable()))
                    if currentRow is None : 
                        MacTblRow = MacTblItem.getRowByIdx(Rowidx)
                    else :
                        MacTblRow = currentRow
                    MacTblCols = MacTblItem.GetColumnNamesForTable()
                    self.logger.info("{0} - MacTblCols : {1}".format(calling_func, MacTblCols))
                    if MacTblRow is not None :
                        self.logger.info("{0} - MacTblRow : {1}".format(calling_func, MacTblRow))
                        pass
                    else :
                        #raise Exception("No memtable record found for RowIDx {0}".format(Rowidx))      
                        MacTblRow = [""] * len(MacTblCols)
                    try:
                        """
                        regex sub : for every pattern matched string substitue required value in func checkAndReplace_CT_items
                        """
                        myDataOut = regexPatern.sub(CheckReplace_Macro_Items, myDataOut)
                    except SPFMacroNotFoundException as SPFMacroNotFoundErr:
                        self.logger.info("{0} - MacTblIdx : {1}".format(calling_func, MacTblIdx))
                        if MacTblIdx < len(parentMacTables) -1:
                            #there are MacTbls yet to be processed...continue
                            pass
                        else:
                            #this is the last MacTable, yet Macro translation not found...hence raise error
                            raise
                    #self.logger.debug("{0} - myDataOut : {1}".format(calling_func,myDataOut))
            except Exception as Err:
                self.logger.exception("{0} - ".format(calling_func, Err))
                raise
            """
            validate for wrong format -- ending token not correct
            """
            regexPatern = re.compile(regexPatStrValidateEToken, re.VERBOSE|re.MULTILINE|re.IGNORECASE)
            matchIter = regexPatern.finditer(myDataOut)
            invalidFormatFoundList = [item.group('S_TOKEN') + item.group('MACRO').strip() # SELECT
                                      for item in matchIter # FROM 
                                      if (item.group('MACRO').strip().startswith("%") == False 
                                          and 
                                          item.group('MACRO').strip().upper().startswith("SPF-") == False)] #WHERE
            if len(invalidFormatFoundList) > 0 :
                if len(invalidFormatFoundList) == 1 and invalidFormatFoundList[0] == "<<<spf_datetime" :
                    return myDataOut
                self.logger.debug("{0} - invalid macro format found : {1}".format(calling_func, invalidFormatFoundList))
                raise Exception("ERROR - Could not find Closing Macro token '{0}' for {1}".format(">>>" if MyMode == 0 else "}", invalidFormatFoundList))
            
            return myDataOut
        except Exception as err :
            self.logger.exception("{0} - ".format(calling_func, err.args[0]))
            raise
    #END : def Substitute_Macro    

    #status : Dev done, UT done
    def ChKTab(self, MyFile, aTab=False) :
        """
        '===============================================
        'Determine if a Tab (i.e., " {TAB}" in file name)
        'is specified for file output, and, if so,
        'strip off the {TAB} from the file name
        '
        'INPUT ARGS:
        '----
        ' 1.) MyFile: StringType : File to Process. remove {TAB}
        ' 2.) aTab  : BooleanType : Default False ('N') #Returns Y if {TAB} present.N otherwise
        'OUPUT : (multiple)
        '===============================================
        ' 1.) MyFile: StringType :  Returns File Name without {TAB}, if there
        ' 2.) aTab  : BooleanType : Returns True ('Y') if {TAB} present.False ('N') otherwise
        ' 
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW30.5'15       Nataraj     Initial Version
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        txtToCheck_TAB = " {TAB}"
        self.logger.info("{0} - MyFile : {1}".format(calling_func, MyFile))
        #MyFile = MyFile if not MyFile is None else ""
        if (not MyFile is None and len(MyFile.strip()) > 0) :
            MyPos = MyFile.upper().find(txtToCheck_TAB)
            self.logger.info("{0} - MyPos : {1}".format(calling_func, MyPos))
            if MyPos > 0 :
                aTab = True
                MyFile = MyFile[:MyPos]
        self.logger.info("{0} - MyFile : {1}".format(calling_func, MyFile))
        self.logger.info("{0} - aTab : {1}".format(calling_func, aTab))
        return MyFile, aTab
    #END : def ChKTab

    #status : dev done, UT done
    def ProcessTS(self, MyFile) :
        """
        '=========================================================
        'Process any Timestamp request in a File Name
        'Timestamp denoted by presence of {TS} in file name.
        '
        'INPUT ARGS:
        '-----------
        ' 1.) MyFile : StringType : File to Process. May contain {TS} or {TAB} designator
        'OUTPUT : 
        '--------
        ' 1.) MyFile : StringType : {TS} updated with timestamp value 
        '----------- 
        ' HISTORY :
        '-----------
        '   Ver         WW'YY           Author      Description
        '   ----        -----           ------      -----------
        '   1.0         WW30.5'15       Nataraj     Initial Version
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        txtToCheck_TS = "{TS}"
        txtToCheck_TAB = " {TAB}"
        self.logger.info("{0} - MyFile : {1}".format(calling_func, MyFile))

        #clean up {TAB}
        MyFile, aTab = self.ChKTab(MyFile)
        
        #processTS start
        if MyFile.find(txtToCheck_TS) > 0 :
            #found TS -- construct TS string
            TS = "_{0}".format(datetime.now().strftime("%Y%b%d%H%M%S"))
            self.logger.debug("{0} - TS : {1}".format(calling_func, TS))
            MyFile = MyFile.replace(txtToCheck_TS, "")
            self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
            MyFilepath, MyFileNameWExt = os.path.split(MyFile)
            self.logger.debug("{0} - MyFilepath : {1}".format(calling_func, MyFilepath))
            self.logger.debug("{0} - MyFileNameWExt : {1}".format(calling_func, MyFileNameWExt))

            MyFileNameStem, MyFileNameExt = os.path.splitext(MyFileNameWExt.strip())
            self.logger.debug("{0} - MyFileNameStem : {1}".format(calling_func, MyFileNameStem))
            self.logger.debug("{0} - MyFileNameExt : {1}".format(calling_func, MyFileNameExt))

            MyFile = "{0}{1}{2}{3}".format(MyFileNameStem.strip(),
                                           TS,
                                           MyFileNameExt.strip(), 
                                           txtToCheck_TAB if aTab == True else "")
            self.logger.debug("{0} - TS updated MyFile : {1}".format(calling_func, MyFile))

            MyFile = os.path.join (MyFilepath, MyFile)
            self.logger.info("{0} - MyFile : {1}".format(calling_func, MyFile))

        return MyFile
    #END : def ProcessTS

