    def DoCreateFileA(self, MyFile, Command1, MyText, Mode="w", content_encoding=None, use_utf_8_sig:bool = False):
        """
        '===================
        'Write data to file. 
        'Retry if necessary
        '
        'ARGS:
        '----
        'MyFile  : File to Open
        'Command1: Text to write
        'MyText  : Notes for err msg
        'Mode :     'w' for create new file(default), 'a' for append mode
        'content_encoding : str : _if_ 'None' (default) : ecoding will be determined _else_ value : specified then it will be used while writing the file
        'MyMode  : 1=Write;0=Writeline #dropped
        '
        'gMyAbort:Y=fatal err # dropped -- will raise error caller needs to handle 
        '===================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        MaxCtr=15
        Ctr = 1
        isFitForRetry = True

        self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
        self.logger.debug("{0} - len(Command1) : {1}".format(calling_func, len(str(Command1))))
        self.logger.debug("{0} - MyText : {1}".format(calling_func, MyText))
        self.logger.debug("{0} - Mode : {1}".format(calling_func, Mode))
                
        if MyFile is None :
            errMsg = "No file argument passed ..."
            if MyText is not None :
                errMsg = "{0}\nCalling Routine:{1}".format(errMsg, MyText)

            raise Exception(errMsg)
        #END : if MyFile is None
        MyFile = os.path.abspath(os.path.expandvars(MyFile.strip()))

        while (isFitForRetry == True) :
            try :
                if content_encoding is None:
                    content_encoding = self.detectCharacterEncoding(Command1.encode(), use_utf_8_sig=use_utf_8_sig) # detect encoding based on Command1 content

                with open(MyFile, Mode, encoding=content_encoding) as fileToWrite:
                    fileToWrite.write(Command1)

                self.logger.debug("{0} - written MyFile : {1}".format(calling_func, MyFile))

                isFitForRetry = False #done creating the file -- exit
            except Exception as err :
                self.logger.exception("{0} - {1}".format(calling_func, err))
                errMsg = ""
                if type(err) is PermissionError:
                    errMsg = err.args[1]
                else:
                    errMsg = err.args[0]

                if Ctr < MaxCtr :
                    errMsg = "   Error:{0} Retry ...{1}".format(errMsg, Ctr)
                    self.Console(errMsg)
                    time.sleep(2) #sleep for 2 seconds
                    Ctr = Ctr + 1
                else :
                    isFitForRetry = False
                    errMsg = "File not writeable:{0}".format(MyFile)
                    if MyText is not None :
                        errMsg = "{0}\nCalling Routine:{1}".format(errMsg, MyText)

                    raise Exception(errMsg)
        #END : while (isFitForRetry == True)
    #END : def DoCreateFileA

    #status : dev done
    def DoAppendFileA(self, MyFile, Command1, MyText):
        """
        '===================
        'Append data to file. 
        'Retry if necessary
        '
        'ARGS:
        '----
        'MyFile  : File to Open
        'Command1: Text to write
        'MyText  : Notes for err msg
        'MyMode  : 1=Write;0=Writeline -- Dropped in py
        '
        'gMyAbort:Y=fatal err
        '===================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
                
        if MyFile is None :
            errMsg = "No file argument passed ..."
            if not MyText is None :
                errMsg = "{0}\nCalling Routine:{1}".format(errMsg, MyText)
            raise Exception(errMsg)
        #END : if MyFile is None

        MyFile = os.path.abspath(MyFile.strip())

        if os.path.exists(MyFile) is False :
            errMsg = "File not found:".format(MyFile)
            if not MyText is None :
                errMsg = "{0}\nCalling Routine:{1}".format(errMsg, MyText)
                self.gMyAbort = True
            raise Exception(errMsg)
        #now call DoCreateFileA with Mode = 'a' (append)
        self.DoCreateFileA(MyFile, Command1, MyText,'a')
    #END : def DoAppendFileA

    def SPFDelete(self, MySrc, quietMode=True, forceDelete=True, displayPrompt=True) :
        """v2.5
        '==================================================================
        'Deletes files in a folder. Wildcards may
        'be used. If a dir is specified,
        'all files within folder will be deleted
        '
        'Arg:
        '===
        'MySrc: File to delete. *=wild card
        'MyOpt: Y to not prompt if DEL *.*
        '==================================================================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - To delete MySrc: {1}".format(calling_func, MySrc))
        self.logger.debug("{0} - quietMode: {1}".format(calling_func, quietMode))
        self.logger.debug("{0} - forceDelete: {1}".format(calling_func, forceDelete))
        cmdRunPassCodes = [0]
        cmdToRun = "%COMSPEC%" 
        cmdArgsList = ["/c"] 
        try : 

            if displayPrompt is True :
                self.ConsoleWithTimeStamp("Starting Delete Applet, v2.5")

            if self.IsEmptyOrNone(MySrc) is True :
                self.Console("No delete files specified ...")
                return
            
            rdr = csv.reader(StringIO(MySrc), 
                             delimiter=",", 
                             skipinitialspace=True)

            #MySrc = ",".join(['"{0}"'.format(re.sub("<c>", ",", item1.strip('"'), re.IGNORECASE)) for item1 in (rdr.next() if isPYTHON2 else next(rdr)) if item1.strip('\'" ') != ""])
            MySrc = ",".join(['"{0}"'.format(re.sub("<c>", ",", item1.strip('"'), re.IGNORECASE)) for item1 in next(rdr) if item1.strip('\'" ') != ""])
            self.logger.debug("{0} - parsed MySrc: {1}".format(calling_func, MySrc))
            if self.IsEmptyOrNone(MySrc) is True : 
                self.Console("No delete files specified ...")
                return

            #start building args to run in DOS
            FileToDeleteFound = []
            cmdArgsList.append("&&Del")

            if forceDelete is True :
                cmdArgsList.append("/F")

            if quietMode is True :
                cmdArgsList.append("/Q")
                if displayPrompt is True : 
                    self.Console(' Deleting "{0}" with No Prompt for *.*, including Read-Only Files ...'.format('","'.join(MySrc.split(","))))
            else : 
                if displayPrompt is True : 
                    self.Console(' Deleting "{0}"'.format(MySrc))

            FileToDeleteFound.append(MySrc)

            
            cmdArgsList = cmdArgsList + FileToDeleteFound
            try :
                Final_CleanUpStatus, runExitCode = self.Run(cmdToRun, cmdArgsList, cmdRunPassCodes, usePopen=True)
                self.logger.debug("{0} - deleted File : {1}".format(calling_func, MySrc))
            except Exception as err:
                pass # no action needed pass

            if displayPrompt is True : 
                self.ConsoleDoneWithoutTimeStamp()
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise            

