    def ReplaceHdrs(self, MyHdrs, MyFile, MyOldFile=None, NoERow=False) :
        """
        '===========================================
        'Replace Headers in an Output files
        '
        'INPUT ARGS:
        '-----------
        'MyHdrs: Headers to replace in format col1[=]newcol1,col2[=]newcol2
        'MyFile: File to Process
        'MyLocal: Local exe or N #in VA : never used hence dropped
        'MyOldFile: Optional source file. May be empty if MyFile i source and destination
        'NoERow : True (VA: Y) if empty rows should also be removed
        '
        'GLOBALS:
        '-------
        'gMyAbort    : Set to Y for fatal err
        'gSPFVaryLib : SPF Library Depending how run
        '===========================================
        """
        #local variables
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        RNStr = None
        MyHf = None
        MyTF = None
        MyEf = None
        CMDArguments = []

        self.logger.debug("{0} - MyHdrs : {1}".format(calling_func, MyHdrs))
        self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
        #dropped
        #self.logger.debug("{0} - MyLocal : {1}".format(calling_func, MyLocal))
        self.logger.debug("{0} - MyOldFile : {1}".format(calling_func, MyOldFile))
        self.logger.debug("{0} - NoERow : {1}".format(calling_func, NoERow))
        try :
            if MyHdrs is not None and MyFile is not None :
                self.Console("   Replace Headers ...{0}".format(self.DatetimeNow))
                RNStr = self.RandomNumStr
                MyHf = self.PrepFile("{0}.hcsv".format(RNStr))
                if MyOldFile is None :
                    MyTF = self.PrepFile("{0}.tcsv".format(RNStr))
                    CMDToExecute = "move"
                    CMDArguments.append("/Y")
                    CMDArguments.append('"{0}"'.format(MyFile.strip('"')))
                    CMDArguments.append('"{0}"'.format(MyTF.strip('"')))
                    runStatus, runExitCode = self.Run(CMDToExecute, CMDArguments)
                    self.logger.debug("{0} - runStatus : {1}".format(calling_func, runStatus))
                    self.logger.debug("{0} - runExitCode : {1}".format(calling_func, runExitCode))
                    CMDArguments = [] #reset
                else :
                    MyTF = self.PrepFile(MyOldFile)
                MyEf = self.PrepFile("{0}.ecsv".format(RNStr))
                MyFile = self.PrepFile(MyFile)

                b2 = os.path.join(self.gSPFVaryLib, "replaceheaders.exe")
                self.logger.debug("{0} - RNStr : {1}".format(calling_func, RNStr))
                self.logger.debug("{0} - MyHf : {1}".format(calling_func, MyHf))
                self.logger.debug("{0} - MyTF : {1}".format(calling_func, MyTF))
                self.logger.debug("{0} - MyEf : {1}".format(calling_func, MyEf))
                self.logger.debug("{0} - MyFile : {1}".format(calling_func, MyFile))
                self.logger.debug("{0} - b2 : {1}".format(calling_func, b2))

                #create header file
                self.DoCreateFileA(MyHf, MyHdrs, "Write-File")
                #prep Run args
                CMDToExecute = b2
                CMDArguments.append('/OutFile="{0}"'.format(MyFile.strip('"')))
                CMDArguments.append('/InFile="{0}"'.format(MyTF.strip('"')))
                CMDArguments.append('/HeaderFile="{0}"'.format(MyHf.strip('"')))
                CMDArguments.append('/LogFile="{0}"'.format(MyEf.strip('"')))

                if NoERow == True :
                    CMDArguments.append("/NoEmptyRow=Y")                

                #now execute run
                runStatus, runExitCode = self.Run(CMDToExecute, CMDArguments)
                self.logger.debug("{0} - runStatus : {1}".format(calling_func, runStatus))
                self.logger.debug("{0} - runExitCode : {1}".format(calling_func, runExitCode))

                if os.path.exists(MyEf) :
                    self.DelAFile(MyEf)
                    raise Exception("Error in ReplaceHdrs")

                #clean up
                self.DelAFile(MyTF)
                self.DelAFile(MyHf)
                self.ConsoleDoneWithTimeStamp()
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def ReplaceHdrs

    def GetHeadersFromParquetFile(self, AFile):
        """
        'Returns list headers(column names) from given parquet file
        """
        from pyarrow import parquet
        myHdrs = []
        try:
            _tmpSchema = parquet.ParquetFile(AFile).schema
            myHdrs = _tmpSchema.names
            del _tmpSchema
        except Exception as err:
            self.logger.exception(f"Error while getting schema of parquet file. {err}")
            raise
        return myHdrs

    #status : dev done, UT done
    def GetHeadersFromFile(self, AFile, fileDLM=None, ll_UniqueHdr=False, l_Replace=False, raiseErrIfNoHdrs=True, convertToUpperCase=False, AFile_encoding=None) :
        """
        '========================================
        'Returns list headers(column names) from given file
        '
        'ARGS:
        '----
        'AFile : File to process
        'fileDLM : if passed file extension has been updated to a non standard value
        'll_UniqueHdr : Make Hive Col Hdrs Unique : Default -> False if True then call Make_Headers_Unique2
        'l_Replace: if True : Replace [] with () (Default is False) -- #V38_47 changes
        'raiseErrIfNoHdrs : (default:True) if True raise error if No headers found/empty list
        'convertToUpperCase : if True convert column to upper case
        'AFile_encoding : encoding to use while reading the file. If None then encoding is determined
        '========================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        AllColNamesList = []

        self.logger.debug("{0} - AFile: {1}".format(calling_func, AFile))
        self.logger.debug("{0} - fileDLM: {1}".format(calling_func, fileDLM))
        self.logger.debug("{0} - ll_UniqueHdr: {1}".format(calling_func, ll_UniqueHdr))
        self.logger.debug("{0} - l_Replace: {1}".format(calling_func, l_Replace))
        self.logger.debug("{0} - raiseErrIfNoHdrs: {1}".format(calling_func, raiseErrIfNoHdrs))
        self.logger.debug("{0} - convertToUpperCase: {1}".format(calling_func, convertToUpperCase))
        self.logger.debug("{0} - AFile_encoding: {1}".format(calling_func, AFile_encoding))
        try : 
            if os.path.exists(AFile) == False :
                errMsg = "Could not find file : {0}".format(AFile)
                raise FileNotFoundError(errMsg)

            if Path(AFile).suffix.upper() == ".PARQUET":
                #this is a parquet file
                AllColNamesList = self.GetHeadersFromParquetFile(AFile=AFile)
            else:
                #regular txt source file
                if fileDLM is None:
                    fileDLM = self.GetFileDLM(AFile)
                if AFile_encoding in [None, ""]:
                    AFile_encoding = self.detectFileEncoding(AFile)
                with open(AFile,'rt', encoding=AFile_encoding, errors='replace') as sourceFile:  #, errors='replace'  #self.gOSDefaultEncoding
                    myCSVReader = csv.reader(sourceFile, delimiter=fileDLM, skipinitialspace=True)
                    AllColNamesList = next(myCSVReader)

            try :
                #check 'Empty column Header
                # AllColNamesList = [colItem.strip() if self.IsEmptyOrNone(colItem) is False else "_Unknown_" for colItem in AllColNamesList]
                AllColNamesList = [colItem.strip() if self.IsEmptyOrNone(colItem) is False else "" for colItem in AllColNamesList]
            except StopIteration as stopIter_err:
                if raiseErrIfNoHdrs is True : raise Exception("Empty File")
            except Exception as err: 
                if len(err.args[0].strip()) == 0 :
                    if raiseErrIfNoHdrs is True : raise Exception("Empty File")
                else :
                    if raiseErrIfNoHdrs is True : raise


            if raiseErrIfNoHdrs is True : #explicitly check headers list has values
                if len(AllColNamesList) == 0 or self.IsEmptyOrNone("".join(AllColNamesList).strip()) is True :
                    errMsg = "No Headers in File : {0}".format(AFile)
                    raise Exception(errMsg)

            self.logger.debug("{0} - colnames : {1}".format(calling_func, AllColNamesList))
            if not ll_UniqueHdr is False : 
                AllColNamesList = self.Make_Headers_Unique2(AllColNamesList)
            if l_Replace is True : #Replace [] with ()
                AllColNamesList = [colItem.replace("[","(").replace("]",")") for colItem in AllColNamesList]
            if convertToUpperCase is True:
                AllColNamesList = [colItem.upper() for colItem in AllColNamesList]
            return AllColNamesList
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def GetHeadersFromFile
    def GetFileLine1(self, AFile) : 
        """
        '========================================
        'Returns Line 1 in a file
        'Note: removes trailing \r\n
        '
        'ARGS:
        '----
        'AFile : File to process
        '========================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        line1 = None

        self.logger.debug("{0} - {1}".format(calling_func, AFile))
        try : 
            if os.path.exists(AFile) == False :
                errMsg = "Could not find file : {0}".format(AFile)
                raise Exception(errMsg)

            with open(AFile,'r', encoding=self.detectFileEncoding(AFile), errors='replace') as sourceFile:
                line1 = sourceFile.readline().rstrip() #rstrip removes trailing \r\n

            self.logger.debug("{0} - line1 : {1}".format(calling_func, line1))
            return line1
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def GetFileLine1

