    def Send_To_Term_Row (self, row, columns, OutTT=True, ll_NoHdrs=False, UsesRowFactory=False, isFirstRow=False) :
        """
        '===================================================
        'Output Data in a cursor row to the terminal. Using tabulate module
        '
        'ARGS:
        '----
        'row: this is a cursor row item (single row) 
        'columns : this is a list of columns (headers) for the row data
        'OutTT   : True (Y) to output to the terminal
        'MyLocal :N if job is being run in batch #dropped use from SPFGlobals.gMyLocal
        'll_NoHdrs: True (Y) if no headers in src file
        'UsesRowFactory : True : to indicate that the row is a dictionary. This will force to parse the rows using the columns data
        'isFirstRow : True : indicates that this is the first row and need to prind columns (headers)...
                if False : then not the first row and need not print the columns(headers)....
        '===================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - row : {1}".format(calling_func, row))
        self.logger.debug("{0} - columns : {1}".format(calling_func, columns))
        self.logger.debug("{0} - OutTT : {1}".format(calling_func, OutTT))
        self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
        self.logger.debug("{0} - UsesRowFactory : {1}".format(calling_func, UsesRowFactory))
        self.logger.debug("{0} - isFirstRow : {1}".format(calling_func, isFirstRow))
        try :
            if OutTT == True and self.gMyLocal != "N":
                if row is not None:
                    if UsesRowFactory is True :
                        #row is dictionary -- tranform to a list
                        rowDataAsList = [[row[colItem] for colItem in columns]]
                    else : 
                        rowDataAsList = [row]
                else :
                    rowDataAsList = ["" for colItem in columns]
                self.logger.debug("{0} - rowDataAsList : {1}".format(calling_func, rowDataAsList))
                tblOut = tblate.tabulate(rowDataAsList, headers=columns, numalign="decimal",stralign="left")
                if isFirstRow is True :
                    if ll_NoHdrs is True :
                        tblOut = "\n".join(tblOut.split("\n")[1:]) #strip of headers line
                else : #not the first row
                    tblOut = "\n".join(tblOut.split("\n")[2:]) #strip of headers line and dashline
                self.Console(tblOut, False)

        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            self.logger.debug("{0} - UsesRowFactory : {1}".format(calling_func, UsesRowFactory))
            self.logger.debug("{0} - OutTT : {1}".format(calling_func, OutTT))
            self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
            self.logger.debug("{0} - row : {1}".format(calling_func, row))
            self.logger.debug("{0} - columns : {1}".format(calling_func, columns))
            self.logger.debug("{0} - isFirstRow : {1}".format(calling_func, isFirstRow))
            self.logger.debug("{0} - OutTT : {1}".format(calling_func, OutTT))
            errMsg = ("The data could not be displayed to the terminal. Error ...\n"
                      "{0}\n"
                      "... occurred during the display process. Continuing on ..."
                      ).format(err.args[0])
            self.Cons80()
            self.Console(errMsg)
            self.Cons80()
    #END : def Send_To_Term_Row

