    def isParquetFile(self, myFile):
        """
        '=============================================================
        'Tests if file has a parquet extension. Returns True if does
        'and False otherwise
       '
        'ARGS:
        '----
        ' MyFile: File to check
        '===========================================================
        """
        try:
            isParquet=False
            if self.IsEmptyOrNone(myFile) is False:
                fileName, fileExt = os.path.splitext(myFile)
                if self.IsEmptyOrNone(fileExt) is False:
                    if fileExt.strip().upper() == ".PARQUET":
                        isParquet=True
            return isParquet
        except Exception as err:
            raise
            
    def Check_SQLite_File (self, MyHeaders, MyOutFile, FinalRow, ll_NoHdrs=False) :
        """
        '=============================================================
        'Checks if the SQLite Output file is empty. If so, add col hdrs
        '
        'ARGS:
        '----
        ' MyHeaders: Col Headers
        ' MyOutFile: O/P file to check
        ' FinalRow : If set to -1, no rows returned regardless of whether MyOutFile exists or has data.
        '            MyOutFile may have previously existed, for e.g.
        '===========================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        MyEmpty = 0
        self.logger.debug("{0} - MyHeaders : {1}".format(calling_func, MyHeaders))
        self.logger.debug("{0} - MyOutFile : {1}".format(calling_func, MyOutFile))
        self.logger.debug("{0} - FinalRow : {1}".format(calling_func, FinalRow))
        self.logger.debug("{0} - ll_NoHdrs : {1}".format(calling_func, ll_NoHdrs))
        try :
            if self.IsEmptyOrNone(MyOutFile) is False and ll_NoHdrs is False and MyHeaders is not None :
                isParquet=self.isParquetFile(MyOutFile)
                if isParquet==False:
                    DLM00 = self.GetFileDLM(MyOutFile)
                    LineHdr = DLM00.join(MyHeaders.split(","))
                else:
                    LineHdr = MyHeaders               
                self.logger.debug("{0} - LineHdr : {1}".format(calling_func, LineHdr))
                if FinalRow == -1 :
                    MyEmpty = 1
                else :
                    if os.path.exists(os.path.abspath(MyOutFile)) == False :
                        MyEmpty = 1
                    else :
                        if isParquet==False:
                            Line1 = self.GetFileLine1(MyOutFile)
                            self.logger.debug("{0} - Line1 : {1}".format(calling_func, Line1))
                            if Line1 is None :
                                MyEmpty = 1
                            elif len(Line1.strip(' "{0}'.format(DLM00))) == 0 :
                                MyEmpty = 1
                    #END : if os.path.exists(os.path.abspath(MyOutFile)) == False :
                #END : if FinalRow == -1 :
                """
                '=========================================
                'If File is Empty or no rows were returned, 
                'then Create results file with column headers
                '=========================================
                """
                self.logger.debug("{0} - MyEmpty : {1}".format(calling_func, MyEmpty))
                if MyEmpty == 1 :
                    if isParquet==False:
                        self.DoCreateFileA(MyOutFile, LineHdr, "Check_SQLite_File")
                    else: #CreateParquet Output file
                        header_list = LineHdr.split(',')
                        df = pd.DataFrame(columns=header_list)
                        df.to_parquet(MyOutFile, index=False)
            #END : if self.IsEmptyOrNone(MyOutFile) is False and ll_NoHdrs is False :
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def Check_SQLite_File

