    def CompareVars(self, MyVar1, MyVar2, MyOpr='EQS', MyMode="Y") :
        """
        'Compares numeric or character string data 
        & returns True ('Y') if comparison is true else False ('N') 
        'ARGS:
        '----
        'MyVar1 : First variable to compare
        'MyVar2 : Second variable to compare. If MyOpr = BT or BTS,should be a comma separating lower and upper
        'MyOpr  : Comparison Operator. If empty, will test an alphanumeric equal. 
        '         EQ, EQS, LE, LES, GE, GES,NE, NES,BT,BTS,GT,GTS,LT,LTS
        'MyMode : Y to handle/exit with conversion errors
        '
        'GLOBALS:
        '-------
        ' gMyABort : Y if should abort
        '
        'INVOKE:
        '------
        'MyIf = CompareVars (MyEnVar, MyVal, MyOpr, "Y")  ("1","1,10","BT") or ("10","20","EQ") ("ABC","DEF","GES")       
        """
        #def __EQ():#+EQS
        #    return True if MyVar1 == MyVar2 else False

        #def __NE():#+NES
        #    return True if MyVar1 != MyVar2 else False

        #def __LE():#+LES
        #    return True if MyVar1 <= MyVar2 else False

        #def __GE():#+GES
        #    return True if MyVar1 >= MyVar2 else False

        #def __LT():#+LTS
        #    return True if MyVar1 < MyVar2 else False

        #def __GT():#+GTS
        #    return True if MyVar1 > MyVar2 else False

        #def __BT():#+BTS
        #    return True if MyVar2 <= MyVar1 <= MyVar3 else False

        #def __NBT():#+NBTS
        #    return True if (MyVar2 < MyVar1 < MyVar3) == False else False

        #locals
        calling_func = "" #self.getCallingFuncName(2, self.__class__.__name__)
        MyErr = "Invalid column for numeric conditional test (datatype mismatch). Exiting job:"   #'======v30.99
        retCompareVars = False #'N'
        MyVar3 = None
        #operDict = {"EQ"  : __EQ,
        #            "EQS" : __EQ,
        #            "NE"  : __NE,
        #            "NES" : __NE,
        #            "LE"  : __LE,
        #            "LES" : __LE,
        #            "GE"  : __GE,
        #            "GES" : __GE,
        #            "LT"  : __LT,
        #            "GT"  : __GT,
        #            "BT"  : __BT,
        #            "BTS"  : __BT,
        #            "NBT"  : __NBT,
        #            "NBTS"  : __NBT}

        #self.logger.debug("{0} - MyVar1: '{1}'".format(calling_func, MyVar1))
        #self.logger.debug("{0} - MyVar2: '{1}'".format(calling_func, MyVar2))
        #self.logger.debug("{0} - MyOpr: '{1}'".format(calling_func, MyOpr))
        #self.logger.debug("{0} - MyMode: '{1}'".format(calling_func, MyMode))
        try :          
            #check for MyOper
            if self.IsEmptyOrNone(MyOpr) is True :
                MyOpr = "EQS"
                self.logger.debug("{0} - updated default MyOpr: '{1}'".format(calling_func, MyOpr))

            if MyOpr in ["EQ", "EQS", "NE", "NES"] and self.IsEmptyOrNone(MyVar2) is True :
                MyVar2 = "&NBSP;"
                if MyOpr[-1] != "S" :
                    MyOpr = "{0}S".format(MyOpr)
                    self.logger.debug("{0} - updated MyOpr: '{1}'".format(calling_func, MyOpr))

            if MyOpr[-1] != "S" :
                try : 
                    #MyVar1 = int(MyVar1) 
                    MyVar1 = float(MyVar1) 
                except Exception as err:
                    self.logger.warn("{0} - {1}".format(calling_func, err.args[0]))
                    if MyMode == "Y" :
                        errMsg = "{0} {1}".format(MyErr, MyVar1)
                        #self.Console(errMsg)
                        raise Exception(errMsg) #'==== v30.99 ===
                    self.logger.debug("{0} - MyVar1.isdigit() err retCompareVars: '{1}'".format(calling_func, retCompareVars))
                    return retCompareVars

                 
            if MyOpr in ["BT", "BTS", "NBT", "NBTS"] :
                try :
                    #now extract the var2(low), var3(high) from var2
                    rdr = csv.reader(StringIO(MyVar2), 
                                     delimiter=",", 
                                     skipinitialspace=True)
                    MyVar2, MyVar3 = next(rdr)
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    errMsg = ("The Between value was in the wrong format. SQLPathFinder expects a low and high value separated by a comma. E.g., '0,10'\n"
                              "Value got : '{0}'\n"
                              "Setting conditional Test False"
                              ).format(MyVar2)
                    raise Exception(errMsg)

                if MyOpr in ["BT", "NBT"] :
                    try : 
                        try : 
                           #MyVar2 = int(MyVar2) 
                           MyVar2 = float(MyVar2) 
                        except Exception as err:
                            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                            errMsg = "{0} {1}".format(MyErr, MyVar2)
                            raise Exception(errMsg)

                        try : 
                           #MyVar3 = int(MyVar3) 
                           MyVar3 = float(MyVar3) 
                        except Exception as err:
                            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                            errMsg = "{0} {1}".format(MyErr, MyVar3)
                            raise Exception(errMsg)
                    except Exception as err:
                        self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                        #region #'==== v30.99 ===
                        self.logger.debug("{0} - ['BT','NBT'] err retCompareVars: '{1}'".format(calling_func, retCompareVars))
                        if MyMode == "Y" :
                            #self.Console(err.args[0])
                            raise Exception(err.args[0]) 
                        #endregion #'==== v30.99 ===
            else : #'Not BT,BTS,NBT,NBTS
                try : 
                    if MyOpr[-1] != "S" :
                        try : 
                           #MyVar2 = int(MyVar2) 
                           MyVar2 = float(MyVar2) 
                        except Exception as err:
                            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                            errMsg = "{0} {1}".format(MyErr, MyVar2)
                            raise Exception(errMsg)
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    if MyMode == "Y" :
                        raise Exception(err.args[0]) #'==== v30.99 ===
                    else : 
                        self.logger.debug("{0} - not ['BT','NBT'] err retCompareVars: '{1}'".format(calling_func, retCompareVars))
                        return retCompareVars

            #self.logger.debug("{0} - MyVar1: '{1}' and type : '{2}'".format(calling_func, MyVar1, type(MyVar1)))
            #self.logger.debug("{0} - MyVar2: '{1}' and type : '{2}'".format(calling_func, MyVar2, type(MyVar2)))
            #self.logger.debug("{0} - MyVar3: '{1}' and type : '{2}'".format(calling_func, MyVar3, type(MyVar3)))

            #call the required operator handler
            #funcToCall = operDict[MyOpr]
            if MyOpr in ["EQ", "EQS"] :
                retCompareVars = True if MyVar1 == MyVar2 else False
            elif MyOpr in ["NE", "NES"] :
                retCompareVars = True if MyVar1 != MyVar2 else False
            elif MyOpr in ["LE", "LES"] :
                retCompareVars = True if MyVar1 <= MyVar2 else False
            elif MyOpr in ["GE", "GES"] :
                retCompareVars = True if MyVar1 >= MyVar2 else False
            elif MyOpr in ["LT", "LTS"] :
                retCompareVars = True if MyVar1 < MyVar2 else False
            elif MyOpr in ["GT", "GTS"] :
                retCompareVars = True if MyVar1 > MyVar2 else False
            elif MyOpr in ["BT", "BTS"] :
                retCompareVars = True if MyVar2 <= MyVar1 <= MyVar3 else False
            elif MyOpr in ["NBT", "NBTS"] :
                retCompareVars = True if (MyVar2 < MyVar1 < MyVar3) == False else False  
            #self.logger.debug("{0} - funcToCall: '{1}'".format(calling_func, funcToCall))
            #retCompareVars = funcToCall()
            #self.logger.debug("{0} - retCompareVars: '{1}'".format(calling_func, retCompareVars))
            return retCompareVars
        except Exception as err:
            self.logger.warn("{0} - {1}".format(calling_func, err.args[0]))
            if MyMode == "Y":
                raise   #'==== v30.99 ===
            self.Console(err.args[0])
            self.logger.debug("{0} - final err retCompareVars: '{1}'".format(calling_func, retCompareVars))
            return retCompareVars
    #END : def CompareVars

