    def Replace_Special_Chars(self, MyTxt, MyMode=0) :
        """
        '===========================================================
        'Replace Special chars in a string with underscores
        '
        ' ARGS:
        ' ----
        '  MyTxt : Text to process
        '  MyMode: 1=>Add additional chars (Default = 0, if 1 then add)
        '
        ' RETURN:
        ' -------
        '  Text with special chars replaced
        '============================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        MyChars = r'?/|<>"*{};[].\/' #'\/Illegal File Name Chars - OS, JMP, SQLPathFinder
        if MyMode > 0 :
            MyChars = "{0} -()&%$#@+':^!~`,".format(MyChars)
            self.logger.debug("{0} - MyChars: '{1}'".format(calling_func, MyChars))

        self.logger.debug("{0} - MyTxt: '{1}'".format(calling_func, MyTxt))
        outValue = "".join("_" if i in MyChars else i for i in MyTxt)
        self.logger.debug("{0} - outValue: '{1}'".format(calling_func, outValue))
        return outValue
    #END : def Replace_Special_Chars

