    def Replace_Special_Chars_Chart(self, MyIn) :
        """
        '================================
        'Replace Special Chars for
        'Interactive Charts
        '
        'ARGS:
        '---
        'MyIn : Input String to Process
        '================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        if self.IsEmptyOrNone(MyIn) is False :
            MyIn = MyIn.replace("<~~~>", '""')
            MyIn = MyIn.replace("<{{{>", chr(13))
            MyIn = MyIn.replace("<}}}>", chr(10))
            MyIn = MyIn.replace("<-s---c->", ';')
        self.logger.debug("{0} - MyIn: '{1}'".format(calling_func, MyIn))
        return MyIn
    #END : def Replace_Special_Chars_Chart

