    def StartJMP(self, MyLocal, LeaveJMPOpen=False) :
        """
        ' create an instance JMP COM object -- using win32com
        'Input :
        '-------
        '1.) MyLocal -- Interactive mode or not
        '2.) LeaveJMPOpen - True/False(d) flag to indicate whether to leave JMPObj visible
        'Output :
        '--------
        '1.) JMPObj - Instance of JMP COM object
        '2.) DoCloseJMP - True/False flag to indicate whether calling client should close/quite JMPObject session
        ' Note: logic of makeMyJMP method from VA is merged into this method

        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        JMPObj = None
        DoCloseJMP = True
        self.logger.info("{0} - LeaveJMPOpen: {1}".format(calling_func,LeaveJMPOpen))
        self.logger.info("{0} - MyLocal: {1}".format(calling_func,MyLocal))
        try : 
            for Cnt in range(1, 6) :
                try : 
                    JMPObj = Dispatch("JMP.Application")
                    if JMPObj != None : 
                        """
                         '=============================================
                         'For interactive use, chk if usr wants to leave
                         'JMP open or do best guess on if JMP open.
                         'For latter, Chk if log has val or any Tbls open
                         '=============================================
                        """
                        if MyLocal != "N" :
                            if (self.IsEmptyOrNone(JMPObj.GetLogContents) == False 
                                or
                               JMPObj.GetNumberOfAutomationDataTables > 0) :
                                DoCloseJMP = False # 'N'
                                JMPObj.Visible = True
                            else : #'JMP ~ open
                                if LeaveJMPOpen == True :
                                    DoCloseJMP = False #'N'
                                    JMPObj.Visible = True
                                else :
                                    JMPObj.Visible = False
                                    
                        if self.gIsSvc is True:
                            self.logger.info("{0} - StartJMP called in SQLPFaaS environment".format(calling_func))
                            DoCloseJMP = True
                            JMPObj.Visible = False
                        break #exit out of for loop
                except Exception as err: 
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    if Cnt == 5 and JMPObj == None :
                        errMsg = "Failed to make JMP object..."
                        self.gMyAbort = True
                        raise Exception(errMsg)
                    else :
                        #Cnt < 5 continue with retry
                        errMsg = "  Could not start JMP (Retry {0}): {1}".format(Cnt, err.args[0])
                        self.Console(errMsg)
                        #5 seconds sleep before next retry
                        time.sleep(5) 
            #END : for Cnt in range(0, 6) :
            self.logger.info("{0} - JMPObj: {1}".format(calling_func, JMPObj))
            self.logger.info("{0} - JMPObj.Visible: {1}".format(calling_func, JMPObj.Visible))
            self.logger.info("{0} - DoCloseJMP: {1}".format(calling_func,DoCloseJMP))
            #we should have a reference to com object here
            return JMPObj, DoCloseJMP
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def StartJMP

    def Chk_Signal (self, MyFile, MyInstance) :
        """
        '====================
        'Process signal files
        '
        'ARGS:
        '----
        'MyFile     : Sig File
        'MyInstance : Instance#
        '====================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyFile: '{1}'".format(calling_func, MyFile))
        self.logger.debug("{0} - MyInstance: '{1}'".format(calling_func, MyInstance))
        try : 
            self.Console("\nWaiting for Email or PowerPoint Command to Appear ...")
            self.WaitFile("{0}.wait".format(MyInstance), 90)
            self.Console("\n")
            openFile_status, fileObj = self.DoOpenFile(MyFile, 1, False, "Chk_Signal")
            try : 
                if openFile_status is True :
                    for line1 in fileObj :
                        line1List = next(csv.reader(StringIO(line1), 
                                                    delimiter=" ", 
                                                    skipinitialspace=True))

                        cmdToExecute = line1List[0]
                        cmdArgs = ['"{0}"'.format(item1) for item1 in line1List[1:]]
                        #self.DoJMPva(line1)
                        runStatus, runExitCode = self.Run(cmdToExecute, cmdArgs)
                        #self.Run(line1,[])
                    #fileObj.close()
            except TypeError as typErr:
                self.logger.exception("{0} - {1}".format(calling_func, typErr.args[0]))
                raise
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            finally:
                self.logger.debug("{0} - in finally block".format(calling_func))
                if not fileObj is None :
                    fileObj.close()

            self.DelAFile(MyFile)

        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def Chk_Signal

    def DoJMPva(self, Command) :
        """
            Implementation of DoJMP.va file
            '==================================================================
            ' Procedure: DoJMP                        Date: 8/17/2014
            '
            ' Interact with JMP to help add images to a PowerPoint presentation
            ' or to email a report
            '
            ' Version History:
            '    Date           Prgrmr         Version     Description
            '   ----------------------------------------------------------------------------
            '    08/17/2011     J.Clarke       1.0         Creation
            '    09/16/2011     J.Clarke       1.1         Use Rectangular shapes with No Text for Image insertion
            '                                              Wait for HTM file to appear before emailing
            '    5/19/2014      J.Clarke       2.0         Run external to JMP
            '    8/17/2014      J.Clarke       2.1         Support Outlook
            '
            ' ARGUMENTS:
            ' ---------
            '  1 : Mode of Operation. E.g., PPT or EMAIL
            '  2 : For PPT   : PPT Input Template
            '      For EMAIL : HTML File to Email
            '  3 : For PPT   : PPT Output File
            '      For EMAIL : Distribution List
            '  4 : For PPT   : Path and Name of File listing Images stored in the same folder as the file which are to be loaded
            '    : For EMAIL : Folder With Images  
            '  5 : For PPT   : N/A
            '    : For EMAIL : Subject Line
            '  6 : ll_Outlook: Y for Outlook
            '
            ' Sample Invocation:
            ' =================
            '   va DoJMP  "PPT" ""  "Out.ppt" "spfgfx_$instance$.images"
            '
            ' GLOBALS:
            ' -------
            '  gMyAbort : Whether to Abort job
            '
            ' NOTES:
            ' ------
            ' Set ObjPRS = ObjPPT.Presentations.Add() 'Create new presentation
            ' set ObjSLD = objPRS.Slides.Add(MyCtr,ppLayoutTitleOnly)
            ' ObjSLD.Shapes(1).TextFrame.TextRange.Text=File.Name
            ' ObjSLD.Shapes(1).TextFrame.TextRange.Font.Size=24
            ' ObjSLD.Shapes.AddPicture MyFile,-1,-1,25,95
            ' SET ObjSLD=NOTHING
            'To add a new slide with blank layout (no title, nosubtitle). There are two arguments in Add() method, first one
            'is to set the slide number. Since we only have one slide, it is set to 1 here. The second one is to set slide
            'layout. “12” is for blank layout, we will use 12 throughout the paper. For the curious minded, one can either
            'play around to see what other number brings to you, or search MSDN library for the list of possible values.
            'To insert a figure into a slide 1, there are eight arguments in AddPictures() method. The first
            'one is the file name of the figure. Second and third arguments tell PowerPoint to make a physical copy of
            'the source figure or a link. We want a physical copy so that slide can be used elsewhere. The value for
            'physical copy is “-1,-1”. The fourth one is the X coordinate of the starting position of the figure from left
            'border, measured in points (72 points=1 inch). The fifth one is the Y coordinate of the starting position of the
            'figure from top border. For this example, test1.emf will be inserted one inch from the left and two inches
            'from the top. The sixth and seventh arguments are to set the size of figure, since we decide to control the
            'size of figure in SAS, we don’t have to use them here.
            'CONST ppLayoutTitleOnly = 11
            'CONST ppLayoutBlank = 12
            'CONST msoTextOrientationHorizontal =  1
            'CONST msoFalse =  0
            'CONST msoTrue  = -1
            'CONST ppAlignCenter = 2
            'CONST msoAlignCenters = 1
            Rem==================================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - Command: '{1}'".format(calling_func, Command))
        self.ConsoleDoneWithTimeStamp("Starting JMP Interaction script, v2.1 ...")
        self.Console("\n")

        raise Exception("DoJMPva not implemented")

    def WaitFile(self, MyFile, MyInterval) : 
        """
        '===============================================
        'Waits some # of seconds for a file to appear
        '
        'ARGS:
        '----
        'MyFile    : File path to chk
        'MyInterval: # times to poll for file before quit
        '================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyFile: '{1}'".format(calling_func, MyFile))
        self.logger.debug("{0} - MyInterval: '{1}'".format(calling_func, MyInterval))
        MySeconds = 10 #seconds
        MyIntVal = 18 #default
        IsFound = False

        try : 
            self.Console("Starting the Wait For File Applet, v1.3 ...")
            MyFile = os.path.abspath(MyFile)
            try :
                if MyInterval.isdigit() == True :
                    MyIntVal = int(MyInterval)
            except AttributeError as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                if err.args[0] == "'int' object has no attribute 'isdigit'" :
                    MyIntVal = int(MyInterval)
                else :
                    raise

            if MyIntVal == 0 :
                MyIntVal = 1
            self.Console("  File to Look For : {0}".format(MyFile))
            self.Console("  Times to Poll    : {0}".format(MyIntVal))

            for i in range(1, MyIntVal+1) :
                if os.path.exists(MyFile) == True :
                    IsFound = True
                    break
                else : 
                    time.sleep(MySeconds)

            if IsFound == True :
                self.Console("  File Found ... {0}".format(self.DatetimeNow))
            else : 
                self.Console("  Time out reached ... {0}".format(self.DatetimeNow))
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def WaitFile

