    def Substitute_Std_Tokens(self, MyText, MyMode, MyFile=None, MyFileDate=None) :
        """
        '=======================================================================
        'Substitute standard date tokens - WW, Day, TS, DOW, or <SP> for a Space
        '
        'ARGS:
        '====
        'MyText: Text to Check
        'MYMODE: format = T 
        '         where T=0|1:How to substitute <TS>
        'MyFile  : File (opt) #defaulted to None in py
        'MyFileDate : Optionally pass MyFile Date if present will not call getFileDate
        'RETURNS:
        '------
        'Substituted Text
        '========================================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        #self.logger.debug("{0} - MyText: '{1}'".format(calling_func, MyText))
        #self.logger.debug("{0} - MyMode: '{1}'".format(calling_func, MyMode))
        #self.logger.debug("{0} - MyFile: '{1}'".format(calling_func, MyFile))
        MyTS = None
        MyDay = None
        MyFDT = ""

        try :
            if MyMode.strip() == "1" :
                MyTS = datetime.now().strftime(self.G_DT_FORMAT_YYYYMMDDhhnnss)
            else : 
                MyTS = datetime.now().strftime(self.G_DT_FORMAT_YYYY_M_DD_HH24_MM_SS)
            #self.logger.debug("{0} - MyTS: '{1}'".format(calling_func, MyTS))

            MyDay = datetime.now().strftime("%Y-%m-%d")
            #self.logger.debug("{0} - MyDay: '{1}'".format(calling_func, MyDay))

            MyDoW = "0{0}".format(datetime.now().isoweekday() + 1)
            #self.logger.debug("{0} - MyDoW: '{1}'".format(calling_func, MyDoW))

            if self.IsEmptyOrNone(MyFile) is False:
                if MyFileDate is None:
                    MyFDT = self.GetFileDate(MyFile)
                else:
                    MyFDT = MyFileDate
                    #self.logger.debug("{0} - MyFDT: '{1}'".format(calling_func, MyFDT))

            Substitute_Std_Tokens_out = MyText
            Substitute_Std_Tokens_out = re.sub(r"\<TS\>", MyTS, Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<TS>", MyTS)
            Substitute_Std_Tokens_out = re.sub(r"\<DAY\>", MyDay, Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<DAY>", MyDay)
            Substitute_Std_Tokens_out = re.sub(r"\<WW\>", self.IntelWW(datetime.now()), Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<WW>", self.IntelWW(datetime.now()))
            Substitute_Std_Tokens_out = re.sub(r"\<DOW\>", MyDoW, Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<DOW>", MyDoW)
            Substitute_Std_Tokens_out = re.sub(r"\<SP\>", "&nbsp;", Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<SP>", "&nbsp;")
            Substitute_Std_Tokens_out = re.sub(r"\<DOF\>", MyFDT, Substitute_Std_Tokens_out, 0, re.IGNORECASE) #Substitute_Std_Tokens_out.replace("<DOF>", MyFDT)

            #self.logger.debug("{0} - Substitute_Std_Tokens_out: '{1}'".format(calling_func, Substitute_Std_Tokens_out))
            return Substitute_Std_Tokens_out
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def Substitute_Std_Tokens
