    def SPOHandler(self, Action, MyURL, MyFile=None):
        """
        """
        #Start - SPOHandler
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        if self.isSPO_URL(MyURL) is True:                
            try:
                if self.SHisSHEntry is True:
                    errMsg = f"Error : Sharepoint online is not supported in Scripthost environment.\n For help, {self.G_Error_Msg_with_HelpPage}"
                    raise Exception(errMsg)
                import clr
                clr.AddReference('SPFSPOHelperLib') #note: initializeSPFBin should have been invoked
                from SPFSPOHelperLib import SPOUploadFile, SPODeleteFile, SPODownloadFile
                SPOActionHandlerMap = {'UPLOADFILE' : (SPOUploadFile, [self.MSALIWAAuthProvider, self.g_SPFSPOParams[5], self.g_SPFSPOParams[6], MyURL, MyFile]),
                                'DOWNLOADFILE' : (SPODownloadFile, [self.MSALIWAAuthProvider, self.g_SPFSPOParams[5], self.g_SPFSPOParams[6], MyURL, MyFile]),
                                'DELETEFILE' : (SPODeleteFile, [self.MSALIWAAuthProvider, self.g_SPFSPOParams[5], self.g_SPFSPOParams[6], MyURL])}
                if (Action not in SPOActionHandlerMap.keys()):
                    raise Exception(f'Invalid Action : {Action}')
                try:
                    self.logger.debug(f"{SPOActionHandlerMap[Action][0]} : {SPOActionHandlerMap[Action][1]}")
                    SPOActionHandler = SPOActionHandlerMap[Action][0](*SPOActionHandlerMap[Action][1])
                    SPOActionHandler.Execute()
                    self.Record_SPF(f"SPO_{SPOActionHandler._version_}_{Action}", self.gMyLocal, self.gMyEXEDir, MyInstance=self.gSPFInstance)
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    raise
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise
        else:
            raise Exception(f'Not a Sharepoint Online URL :{MyURL}')

    def SPOHandler2(self, Action, MyURL, MyFile=None):
        """
        """
        #Start - SPOHandler
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        SPOActionHandler_version_ = "1.0.0.2"
        if self.isSPO_URL(MyURL) is True:                
            try:
                if self.SHisSHEntry is True:
                    errMsg = f"Error : Sharepoint online is not supported in Scripthost environment.\n For help, {self.G_Error_Msg_with_HelpPage}"
                    raise Exception(errMsg)

                runExe = r"SPFBin\SPFSPOHandlerClient.exe"
                if self.gMyLocal == "N":
                    myExePath = self.gSPFVaryLib
                else: #'Interactive
                    myExePath = self.gMyLocal
                self.logger.debug("{0} - myExePath: '{1}'".format(calling_func, myExePath))

                MySrcExe = os.path.join(myExePath, runExe)

                SPOActionHandlerCmdArgsMap = {'UPLOADFILE'   : [f'/SOURCEFILE="{MyFile}"']
                                                , 'DOWNLOADFILE' : [f'/DESTINATIONFILE="{MyFile}"']
                                                , 'DELETEFILE'   : [] #no additional arguments needed for this action
                                                  }
                if (Action not in SPOActionHandlerCmdArgsMap.keys()):
                    raise Exception(f'Invalid Action : {Action}')
                try:
                    _SPOLogMode = self.parseCMDArgsToken(self.gCommandLineArguments, "SPOLOGMODE", defaultTokenValue="N", doUCase=True, doTrim=True)
                    _SPOenableMSALLogging = self.parseCMDArgsToken(self.gCommandLineArguments, "SPOENABLEMSALLOGGING", defaultTokenValue="N", doUCase=True, doTrim=True)
                    cmdArgs = [f'/SPOACTION="{Action}"'
                               , f'/SPOURL="{MyURL}"'
                               ] + SPOActionHandlerCmdArgsMap[Action] + [f"/SPOLOGMODE={_SPOLogMode}", f"/SPOENABLEMSALLOGGING={_SPOenableMSALLogging}"]
                    
                    #self.g_SPFSPOParams[5], self.g_SPFSPOParams[6]

                    runStatus, runCode = self.Run(MySrcExe, cmdArgs, usePopen=False, )
                
                    self.Record_SPF(f"SPO_{SPOActionHandler_version_}", self.gMyLocal, self.gMyEXEDir, MyInstance=self.gSPFInstance)
                except SPFCMDRunExitWithErrorCodeException as SPFCMDExitCodeErr:
                    self.logger.debug("{0} - SPFCMDExitCodeErr.args[0] : {1}".format(calling_func, SPFCMDExitCodeErr.args[0]))
                    self.logger.debug("{0} - SPFCMDExitCodeErr.args[-2] : {1}".format(calling_func, SPFCMDExitCodeErr.args[-2]))
                    raise Exception("Error while executing Query, Exit Code : {0}".format(SPFCMDExitCodeErr.args[-2]))
                except Exception as err:
                    self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                    raise
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise
        else:
            raise Exception(f'Not a Sharepoint Online URL :{MyURL}')

    def isSPO_URL(self, MyURL):
        """
        Check if the URL is a Sharepoint Online URL
        """
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyURL: '{1}'".format(calling_func, MyURL))
        isSPO_URL_out = False       
        if re.match('intel.sharepoint.com', urlparse(MyURL).netloc, re.IGNORECASE):
            isSPO_URL_out = True
        self.logger.debug("{0} - isSPO_URL_out: '{1}'".format(calling_func, isSPO_URL_out))
        return isSPO_URL_out
