    def SPFWebCopy(self, MyLocal, MyURL, MyFile, lInter, lNoAbort) :
        """
        '====================================================
        'Copy file from URL
        '
        'Args:
        '====
        'MyLocal: N for batch run
        'MyURL  : source 
        'MyFile : Path & Name of text File to create
        'lInter : Run Interactively Only
        'lNoAbort : Y:No Abort if Fail
        '
        'GLOBALS:
        '-------
        'gTempDir : SH SPF SW 
        '
        'Invoke:
        '======
        ' Call SPFWebCopy (\"N\",\"http://moss.amr.ith.intel.com/sites/TME_TMGT/ngdss/SQLPathFinderWork/test.csv\","c:\\users\\<user>\\Test.csv",N, N)
        '====================================================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyLocal: '{1}'".format(calling_func, MyLocal))
        self.logger.debug("{0} - MyURL: '{1}'".format(calling_func, MyURL))
        self.logger.debug("{0} - MyFile: '{1}'".format(calling_func, MyFile))
        self.logger.debug("{0} - lInter: '{1}'".format(calling_func, lInter))
        self.logger.debug("{0} - lNoAbort: '{1}'".format(calling_func, lNoAbort))
        
        myExePath = None

        try :
            self.Console("Starting Web Copy Applet V3.3 ...")
            if lNoAbort is not True : #if lNoAbort != "Y" :
                lNoAbort = False #"N"
                self.logger.debug("{0} - lNoAbort: '{1}'".format(calling_func, lNoAbort))

            if self.SHisSHEntry is True : #'SH
                if lInter is True :#if lInter == "Y" :
                    self.Cons80()
                    self.Console("Option 'Run Interactively' set. Exiting Job as running on ScriptHost ...")
                    self.Cons80()
                    return
                myExePath = self.gTempDir
            elif MyLocal == "N" :
                myExePath = self.gSPFVaryLib
            else : #'Interactive
                myExePath = MyLocal

            self.logger.debug("{0} - myExePath: '{1}'".format(calling_func, myExePath))

            if self.IsEmptyOrNone(MyFile) is True or self.IsEmptyOrNone(MyURL) is True :
                self.Cons80()
                self.Console("Some input arguments are missing ...\nExiting ...")
                self.Cons80()
                return
            
            """
            '============================
            'Handle CommodityCost Reports
            '=============================
            """
            tmp1 = MyURL.lower()
            try :
                if re.match(r"(http(s)?\://commoditycost.intel.com/reports/)", tmp1[:40], re.IGNORECASE) and tmp1[-11:] != "&output=tab" :
                    MyURL = "{0}&output=tab".format(MyURL)
                    self.logger.debug("{0} - MyURL commoditycost updated: '{1}'".format(calling_func, MyURL))
            except Exception as err:
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise

            self.Cons80()
            self.Console(" Source File       : {0}".format(MyURL))
            self.Console(" Destination       : {0}".format(MyFile))
            self.Console(" Run Interactively : {0}".format(lInter))
            self.Console(" Continue if fail  : {0}".format(self.convertBoolToYN(lNoAbort)))
            self.Cons80()

            MyFile = os.path.abspath(MyFile) #'Get Abs Path of file

            
            
            #determine external exe path
            myExePath = None

            if self.SHisSHEntry is True : #'SH
                if lInter is True :#if lInter == "Y" :
                    self.Cons80()
                    self.Console("Option 'Run Interactively' set. Exiting Job as running on ScriptHost ...")
                    self.Cons80()
                    return
                myExePath = self.gTempDir
            elif MyLocal == "N" :
                myExePath = self.gSPFVaryLib
            else : #'Interactive
                myExePath = MyLocal
            
            if self.isSPO_URL(MyURL) is True:
                self.SPOHandler2("DOWNLOADFILE", MyURL, MyFile)
                return

            self.logger.debug("{0} - myExePath: '{1}'".format(calling_func, myExePath))

            MySrcExe = os.path.join(myExePath, "Get_Web_Text.exe")

            cmdArgs = ['/from="{0}"'.format(MyURL),
                        '/to="{0}"'.format(MyFile),
                        '/binary="Y"']
            runStatus, runCode = self.Run(MySrcExe, cmdArgs, usePopen=True)
        except Exception as err:
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            errMsg = "  Error Occurred during copy ..."
            self.Console(errMsg)
            if lNoAbort is False:
                self.gMyAbort = True
                raise Exception(errMsg)
    #END : def SPFWebCopy

