        def Generate_SQLite_DT() :
            """
            '===============================================
            'Generates a comma delimited list of SQLite
            'cols & datatypes. E.g., lot(c),outs(n),yield(f)
            '
            'ARGS: Note: in py no args...but ColRow and FmtRow lists are referenced to process the logic
            '----
            'TableDesign : Report Spec Table 
            '
            'RETURNS:
            '-------
            'SQLite cols & datatypes
            '===============================================
            """
            Generate_SQLite_DT_ouptut = ""
            MyData = []
            #ColRowFlattened = self.FlattenAList(ColRow)
            #FmtRowFlattened = self.FlattenAList(FmtRow)

            self.logger.debug("{0} - ColRowFlattened: '{1}'".format(calling_func, ColRowFlattened))
            self.logger.debug("{0} - FmtRowFlattened: '{1}'".format(calling_func, FmtRowFlattened))
            
            for idx, MyColData in enumerate(ColRowFlattened):
                if MyColData is None : 
                    continue
                MyFmt = FmtRowFlattened[idx]
                if not MyFmt is None :
                    MyFmt = self.Get_ColFormat(MyFmt, "D").lower()
                MyData.append("{0}({1})".format(MyColData, MyFmt if MyFmt in ["n", "f"] else "c"))

            Generate_SQLite_DT_ouptut = ",".join(MyData)
            #self.logger.debug("{0} - Generate_SQLite_DT_ouptut: '{1}'".format(calling_func, Generate_SQLite_DT_ouptut))
            return Generate_SQLite_DT_ouptut
        #end of nested function Generate_SQLite_DT

        def Init_RowSpan(memTableName) :
            """
            '==========================
            'Prepare Table to Handle RowSpan Logic
            '
            'ARGS:
            '----
            'memTableName : #Table1: Table With Data to Report      
            '==========================
            """
            #self.logger.debug("{0} - memTableName: '{1}'".format(calling_func, memTableName))
            try : 
                memTableName_Path, memTableName_fileName = os.path.split(memTableName)
                memTableCols2 = TableDesign.GetColumnNamesForTable(memTableName_fileName)
                #self.logger.debug("{0} - memTableCols2: '{1}'".format(calling_func, memTableCols2))
                ROWSPAN_Cols = [colName for colName in memTableCols2 if colName.upper().startswith("_ROWSPAN") is True]
                #self.logger.debug("{0} - ROWSPAN_Cols: '{1}'".format(calling_func, ROWSPAN_Cols))
                for ROWSPAN_idx, ROWSPAN_Col in enumerate(ROWSPAN_Cols) :
                    tmp_JOINCOL = "_JoinCol{0}_".format(ROWSPAN_idx + 1)
                    #sqlStmnt = "SELECT min(rowid), tbl.[{1}], tbl.[{2}] FROM [{0}] tbl WHERE [{1}] != '1' GROUP BY tbl.[{1}], tbl.[{2}]".format(memTableName_fileName, ROWSPAN_Col, tmp_JOINCOL)
                    #cur1 = TableDesign.Run_SQLQuery(sqlStmnt)
                    #TableDesign.writeCursorToFile(cur1, outFile = None, OutExcel=r"c:\temp\Init_rowspan{0}_preout.tab".format(ROWSPAN_idx+1), outTTin=False)

                    sqlStmnt = ("update [{0}] "
                                "set [{1}] = '' "
                                "WHERE [{1}] != '1' "
                                "AND rowid not in( "
                                "SELECT rowid FROM [{0}] tbl "
                                "WHERE NOT EXISTS ( "
                                "SELECT * "
                                "FROM [{0}] t "
                                "WHERE t.[{1}] = tbl.[{1}] "
                                "AND t.rowid = tbl.rowid - 1 "
                                "AND t.[{2}] = tbl.[{2}] "
                                ") "
                                "ORDER BY rowid)").format(memTableName_fileName, ROWSPAN_Col, tmp_JOINCOL)
                    
                    TableDesign.Run_SQLQuery(sqlStmnt)
                
                #sqlStmnt = "SELECT * from [{0}]".format(memTableName_fileName)
                #cur1 = TableDesign.Run_SQLQuery(sqlStmnt)
                #TableDesign.writeCursorToFile(cur1, outFile = None, OutExcel=r"c:\temp\Init_rowspna_out.tab", outTTin=False)

                return memTableCols2 # return the memTables columns 
            except Exception as err: 
                self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
                raise
        #end of nested function Init_RowSpan

