    def ijs_Gen_Prefilter(self, MyColD, FileID, ColDTRowItem, ColWhereOpItem, 
                          ColWhereValItem, MyPreFilterArr):
        """ Added for VA30_134
        helper function to generate prefilter condition for interactive reports

        INPUT : 
        1.) MyColD : Column DataField or Column pattern list 
        2.) FileID : FileID 
        3.) ColDTRowItem : Column Data type 
        4.) ColWhereOpItem : Where clause type   
        5.) ColWhereValItem : Where clause value
        6.) MyPreFilterArr : List of constructed Prefilter -- do_filter(xxxx) statements

        OUTPUT :
        1.) MyPreFilterArr : List of constructed Prefilter -- do_filter(xxxx) statements
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyColD: {1}".format(calling_func, MyColD)) #'Column DataField or Column pattern list
        self.logger.debug("{0} - FileID: {1}".format(calling_func, FileID))
        self.logger.debug("{0} - type(FileID): {1}".format(calling_func, type(FileID)))
        self.logger.debug("{0} - ColDTRowItem: {1}".format(calling_func, ColDTRowItem)) #'Data Type
        self.logger.debug("{0} - ColWhereOpItem: {1}".format(calling_func, ColWhereOpItem))  #MyWOp #'Where Operator
        self.logger.debug("{0} - ColWhereValItem: {1}".format(calling_func, ColWhereValItem)) #'Where Value  , #MyWVal
        self.logger.debug("{0} - MyPreFilterArr: {1}".format(calling_func, MyPreFilterArr))

        if type(MyColD) is list:
            #this is due to matching cols logic...ColRow,HdrRow, ColFmtRow will have a nested list of MatchedCols
            #Need to loop through each item with all other dependent parameters same
            for idx, MyColDItem in enumerate(MyColD):
                MyPreFilterArr = self.ijs_Gen_Prefilter(MyColDItem, FileID, ColDTRowItem, ColWhereOpItem, ColWhereValItem,MyPreFilterArr)
        else:
            if self.IsEmptyOrNone(ColWhereOpItem) is False and self.IsEmptyOrNone(MyColD) is False:
                if MyColD.startswith("{0}:".format(FileID)) is True:
                    MyColD = MyColD.split(":")[1] #'Col Name
                    if re.search("DATE", ColDTRowItem, re.IGNORECASE):
                        MyDT = "d"
                    elif re.search("STRING", ColDTRowItem, re.IGNORECASE):
                        MyDT = "c"
                    elif re.search("FLOAT", ColDTRowItem, re.IGNORECASE):
                        MyDT = "f"
                    else:
                        MyDT = "n"
                MyPreFilterArr.append(list(map(lambda x : '"{0}"'.format(x), [MyColD, MyDT, ColWhereOpItem, ColWhereValItem])))
        self.logger.debug("{0} - MyPreFilterArr: {1}".format(calling_func, MyPreFilterArr))
        return MyPreFilterArr
    #END : def ijs_Gen_Prefilter

    def ijs_Create_ParentGroup(self, MyParentGroupArr, MyCG, z, MyCGArr, MyCase):
        """
        '=== v30.135 ==========
        '==================================
        'Create Column Hiearchy
        '
        'Args:
        '----
        'MyParentGroupArr : List of Column Hiearchy Logic dictionary object -- this will be later converted to JSON string
        'MyCG          : Column Group
        'z             : Next element Number in Hiearchy
        'MyCGArr       : Column Hiearchy Array
        'MyCase        : Case of Col Header, u, l or ""
        '==================================
        """
        #region logging input params
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - MyParentGroupArr : {1}".format(calling_func, MyParentGroupArr))
        self.logger.debug("{0} - MyCG : {1}".format(calling_func, MyCG))
        self.logger.debug("{0} - z : {1}".format(calling_func, z))
        self.logger.debug("{0} - MyCGArr : {1}".format(calling_func, MyCGArr))
        self.logger.debug("{0} - MyCase : {1}".format(calling_func, MyCase))
        #endregion logging input params
        #MyCGID = "name:'{MyCG}'".format(MyCG = MyCG.replace(" ", '').lower())
        #self.logger.debug("{0} - MyCGID : {1}".format(calling_func, MyCGID))
        MyCGID = MyCG.replace(" ", '').lower()
        if MyCase == 'u':
            MyCG = MyCG.upper()
        elif MyCase == 'l':
            MyCG = MyCG.lower()
        foundItem = False
        for idx, MyParentGroupItem in enumerate(MyParentGroupArr):
            if re.match(MyCGID, MyParentGroupItem['name'], re.IGNORECASE):
                foundItem = True
        if foundItem is False:
            tmp = {'name': '{MyCGID}'.format(MyCGID = MyCGID), 'align' : 'center', 'text' : '{MyCG}'.format(MyCG=MyCG)}
            if len(MyCGArr) > z:
                tmp['parentgroup'] = MyCGArr[z].replace(" ", "").lower()
            MyParentGroupArr.append(tmp)
        self.logger.debug("{0} - MyParentGroupArr : {1}".format(calling_func, MyParentGroupArr))
        return MyParentGroupArr

    #END : def ijs_Create_ParentGroup

