    def ijs_Extract_Token(self, Command1, Token) :
        """
        '=========================
        'Extract Token from String
        '
        'ARGS:
        '----
        'Command1: String
        'Token   : Token to Extract
        '=========================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        #self.logger.debug("{0} - Command1 : {1}".format(calling_func, Command1))
        #self.logger.debug("{0} - Token : {1}".format(calling_func, Token))
        ijs_Extract_Token_output = ""
        try :
            if self.IsEmptyOrNone(Token) is False :
                #Token = Token.strip().lower()
                #rePattern ="<{0}>(?P<TokenValue>.*)</{0}>".format(Token)
                MyMatch = re.search("<{0}>(?P<TokenValue>.*)</{0}>".format(Token.strip()), 
                                   Command1, 
                                   re.IGNORECASE|re.MULTILINE)
                #self.logger.debug("{0} - MyMatch : {1}".format(calling_func, MyMatch))
                if not MyMatch is None:
                    ijs_Extract_Token_output = MyMatch.group("TokenValue")
            return ijs_Extract_Token_output
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def ijs_Extract_Token 

    def getRepDesignRowData(self, TableDesign, memTableName, designRowType, startCol=2, ensureOutputArrOfLen=0) :
        """
        Fetch row data for a specific Type in report design table.
        Optionally return columns from specific start poistion (column position)
        startCol = 2 --> Col1. if need to start from another col give the col index number (starting col:TYPE is 0, KEY is 1, Col1 is 2, etc)
        ensureOutputArrOfLen : if data is not present results in in empty list, this param will indicate to fill the arr with empty strings of definite length
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - designRowType : {1}".format(calling_func, designRowType))
        self.logger.debug("{0} - startCol : {1}".format(calling_func, startCol))
        tmpRow = [] #output
        try :
            sqlStmnt = "SELECT * FROM [{0}] WHERE upper(trim([TYPE])) = '{1}'".format(memTableName, designRowType)
            TmpData = TableDesign.Run_SQLQuery(sqlStmnt)
                
            for row in TmpData :
                tmpRow = list(row[startCol:])
            if len(tmpRow) == 0 and ensureOutputArrOfLen > 0:
                tmpRow = [""] * ensureOutputArrOfLen
            self.logger.debug("{0} - len(tmpRow) : {1}".format(calling_func, len(tmpRow)))
            return tmpRow
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def getRepDesignRowData 

    def getRepDesignPropertyValue(self, TableDesign, memTableName, designRowType, propertyCol='KEY', defaultValueIfNull='') :
        """
        Fetch deisgn property 'Key' column for specific Type in report design table.
        return only 1 value
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
