    def ijs_Verify_CSV(self, CSVFile, MyInstance, MyLocal, MyDelFile) :
        """
        '=============================
        'Verify CSV FIle
        '
        'ARGS:
        '----
        'CSVFile(ByRef)    : CSV File to check
        'MyLocal    : Exe path or N for Remote
        'MyInstance : SPF Instance #
        'MyDelFile(ByRef)  : Temp file to Delete
        '
        'OUTPUT : (py)
        '1. CSVFile
        '2. MyDelFile
        '
        'Dropped (output) :
        '1. ijs_Verify_CSV_output -- this is not needed if Succesfull no error is raised and on error calling func needs to handle error
        '=============================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - CSVFile : {1}".format(calling_func, CSVFile))
        self.logger.debug("{0} - MyInstance : {1}".format(calling_func, MyInstance))
        self.logger.debug("{0} - MyLocal : {1}".format(calling_func, MyLocal))
        self.logger.debug("{0} - MyDelFile : {1}".format(calling_func, MyDelFile))
        try :
            if self.IsEmptyOrNone(CSVFile) is True :
                errMsg = "CSVFile not specified"
                raise Exception(errMsg)
            else :
                """
                '=========================
                'Test if this is a web file
                '==========================
                """
                CSVFile = CSVFile.strip()
                if os.path.dirname(CSVFile).lower() in ["http:", "https:"] :
                    CSVFile_fileName, MyExt = os.path.split(CSVFile)
                    if self.IsEmptyOrNone(MyExt) is True :
                        MyExt = ".csv"
                    MyOut = "js_{0}{1}".format(MyInstance, MyExt)
                    self.DelAFile(MyOut)
                    self.SPFWebCopyPy(MyLocal, CSVFile, MyOut, "N", "N")
                    CSVFile = MyOut
                    MyDelFile = MyOut
                #END : if os.path.dirname(CSVFile).lower() in ["http:", "https:"] :
                CSVFile = os.path.abspath(CSVFile)
                if os.path.exists(CSVFile) is False :
                    errMsg = "CSVFile does not exist: {0}".format(CSVFile)
                    raise Exception(errMsg)
            self.logger.debug("{0} - CSVFile : {1}".format(calling_func, CSVFile))
            self.logger.debug("{0} - MyDelFile : {1}".format(calling_func, MyDelFile))
            return CSVFile, MyDelFile
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            #note calling function needs to decide on setting 'self.gMyAbort' value
            raise
    #END : def ijs_Verify_CSV 

