    def ijs_Gen_JSON(self, JName, L, CSVFile,  FileArr, AnyFileArr, ColTop, ColTopVal, SortSQL, SortSpec, MyInstance, 
                     MyLocal, PreProc, JSFile, JSDataAppend, KeepCase) :
        """
        '============================
        'Generate SQL to Create JSON
        '& generate JSON
        '
        'ARGS:
        '----
        'JName            : JS Var Name Stem
        'L                : Counter
        'CSVFile          : CSV File
        'FileArr(ByRef)   : Array with Cols
        'AnyFileArr(ByRef): Does Array exist
        'ColTop    : Op var to divide JSON data
        'ColTopVal : Opt val to divide JSON Data
        'SortSQL   : Opt. Sort for JSON Data
        'SortSpec  : Opt Sort Spec 
        'MyInstance: Instance #
        'MyLocal   : Exe dir or N for remote
        'PreProc   : Y to Pre-process CSV File & strip embedded delims...
        'JSFile    : JS File to Create
        'JSDataAppend(Out)  : 0 to Create or 1 to Append JSData File
        'KeepCase  : 1 to Keep Case or 0 to make Lower case
        '
        'OUTPUT :
        '1. FileArr
        '2. AnyFileArr
        '3. JSAppend
        'GLOBALS:
        '-------
        ' gMyAbort : Y to Abort Job
        '============================
        """
        #locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.logger.debug("{0} - JName : {1}".format(calling_func, JName))
        self.logger.debug("{0} - L : {1}".format(calling_func, L))
        self.logger.debug("{0} - CSVFile : {1}".format(calling_func, CSVFile))
        self.logger.debug("{0} - FileArr : {1}".format(calling_func, FileArr))
        self.logger.debug("{0} - AnyFileArr : {1}".format(calling_func, AnyFileArr))
        self.logger.debug("{0} - ColTop : {1}".format(calling_func, ColTop))
        self.logger.debug("{0} - ColTopVal : {1}".format(calling_func, ColTopVal))
        self.logger.debug("{0} - SortSQL : {1}".format(calling_func, SortSQL))
        self.logger.debug("{0} - SortSpec : {1}".format(calling_func, SortSpec))
        self.logger.debug("{0} - MyInstance : {1}".format(calling_func, MyInstance))
        self.logger.debug("{0} - MyLocal : {1}".format(calling_func, MyLocal))
        self.logger.debug("{0} - PreProc : {1}".format(calling_func, PreProc))
        self.logger.debug("{0} - JSFile : {1}".format(calling_func, JSFile))
        self.logger.debug("{0} - JSDataAppend : {1}".format(calling_func, JSDataAppend))
        self.logger.debug("{0} - KeepCase : {1}".format(calling_func, KeepCase))
        FinalRow = 0
        MySQL_list = []
        MyData1 = []
        MyComma=""
        MySQL='SELECT ",{"'
        try :
            Tmp4 = self.GetFileLine1(CSVFile)
            #IsRowsInFile = self.getRowCountFromFile(CSVFile)
            self.logger.debug("{0} - KeepCase : {1}".format(calling_func, KeepCase))
            if AnyFileArr == 1 :
                del FileArr
            FileArr = self.GetHeadersFromFile(CSVFile)
            AnyFileArr = 1
            for colIdx, col in enumerate(FileArr) :
                FileArr[colIdx] = self.Test_Valid_JQW_Cols(col)
                MyCH = FileArr[colIdx]
                if KeepCase == 0 : MyCH = MyCH.lower()
                if self.IsEmptyOrNone(MyCH) is False :
                    #MySQL = '{0}\n|| \'{1}\' || JsonValue(\'{2}\') || \':\' || JsonValue(COALESCE([{2}], "")) || \'\''.format(MySQL, MyComma, MyCH)
                    MySQL = '{0}\n|| \'{1}\' || JsonKeyValPair(\'{2}\', COALESCE([{2}], "")) || \'\''.format(MySQL, MyComma, MyCH)
                    MyComma = ","
            #MySQL = "SELECT '{\"module\":' || [module] || '\"'"
            #MySQL = "SELECT [module]"
            MySQL = '{0}\n|| \'}}\' AS "jsonData"\nFROM t1'.format(MySQL)
            #MySQL = '{0}\nFROM t1'.format(MySQL)
            if self.IsEmptyOrNone(ColTop) is False : 
                MySQL = "{0}\nWHERE [{1}] = '{2}'".format(MySQL, ColTop, ColTopVal)
            if self.IsEmptyOrNone(SortSQL) is False : 
                MySQL = "{0}\nORDER BY {1}".format(MySQL, SortSQL.lower()) #'ORDER BY Included
            Tmp1 = "t_{0}".format(MyInstance)
            CSVFile_FileNamePart, CSVFile_FileExt = os.path.split(CSVFile)
            if self.IsEmptyOrNone(CSVFile_FileExt) is False :
                Tmp1 = "{0}{1}".format(Tmp1, CSVFile_FileExt)
            else :
                Tmp1 = "{0}.csv".format(Tmp1)
            from SPFLib.SPFUtilities.memtable import MemTable
            mymemTable1 = MemTable()

            FinalRow = mymemTable1.Run_SQLite(Site1="", Command1=MySQL, MyTables= "{0} : t1".format(CSVFile), WorkDir=".\\", OutTT="N", OutFile=None, OutExcel=Tmp1, FinalRow=FinalRow, ExPlans=None,
                                    MyLocal=MyLocal, MyText="QUIET", PreProcCSV=PreProc, MySQLite_DT=SortSpec.lower(), MySQLiteCache="N", ll_QuoteCSV=False, MyEmptyNull=True, ll_UniqueHdr="N",
                                    l_DBName="",l_Null="",ll_SQLiteExt="",ll_NoHdrs=True,ll_Schema="N", MyInstance="",isJQW="Y")
            self.logger.debug("{0} - FinalRow : {1}".format(calling_func, FinalRow))
            if FinalRow == -1 :
                self.gMyAbort = True
                return FileArr, AnyFileArr, JSDataAppend

            if os.path.exists(Tmp1) is True:
                with open(Tmp1, 'r') as objFile:
                    for line in objFile:
                        MyData1.append(line.strip())
                self.DelAFile(Tmp1)
                if len(MyData1) > 0 :
                    #MyData1[0] = MyData1[0][1:] #remove the leading ,
                    #print(MyData1[0]); #Debug
                    poscommai = MyData1[0].find(",")
                    if poscommai != -1:
                        MyData1[0] = MyData1[0][poscommai + 1:] #remove the leading , and anything preceding. E.g., »¿,
                    #print(MyData1[0]); #Debug
            MyData = "var {0}_{1} = [\n {2}\n];\n".format(JName,
                                                        L,
                                                        "\n".join(MyData1)) #"\n,".join(MyData1))
            del MyData1
            MyData=MyData.replace('"null"','null') #replace occurrences of "null" with null
            if JSDataAppend == 0 :
                self.DoCreateFileA(JSFile, MyData, "CSV_To_JSON") #'gMyAbort may be set to Y
                JSDataAppend = 1
            else :
                self.DoAppendFileA(JSFile, MyData, "CSV_To_JSON") #gMyAbort may be set to Y
            self.logger.debug("{0} - output FileArr : {1}".format(calling_func, FileArr))
            self.logger.debug("{0} - output AnyFileArr : {1}".format(calling_func, AnyFileArr))
            self.logger.debug("{0} - output JSDataAppend : {1}".format(calling_func, JSDataAppend))
            return FileArr, AnyFileArr, JSDataAppend
        except Exception as err: 
            self.logger.exception("{0} - {1}".format(calling_func, err.args[0]))
            raise
    #END : def ijs_Gen_JSON
    
