    def load_py_module_source(self, modname: str, filename: str):
        """
        This is a replacement for 'imp.load_source' method that existed in the depricated & obsolete 'imp' module
        ref : https://docs.python.org/3/whatsnew/3.12.html#imp
        """
        __loader = importlib.machinery.SourceFileLoader(modname, filename)
        __spec = importlib.util.spec_from_file_location(modname, filename, loader=__loader)
        __module = importlib.util.module_from_spec(__spec)
        # The module is always executed and not cached in sys.modules.
        # Uncomment the following line to cache the module.
        # sys.modules[__module.__name__] = module
        __loader.exec_module(__module)
        return __module
    #END : def load_py_module_source

