class SPFMutedException(Exception):
    """
    ' raise this exception if intention is to mute the error exception being printed to the console, but query execution to continue as expected
    """
    pass
class SPFCMDRunExitWithErrorCodeException(Exception):
    """
    ' this used in Run() to raise exception when external exe execution return error exit codes
    """
    pass
class SPFMacroNotFoundException(Exception):
    """
    ' this is used to raise/trap/handle exception when macro substitution fails due to macro not found -- especially for nested macros
    """
    pass

class BulkloadDataHandler(Utilities):
    def __init__(self, queryOptions):
        """
        INPUT Args:
        1. queryOptions : a 'types.SimpleNamespace' container object having all the spfsql options parsed. 
                          This is initialized in spfsql3.SPFTaskBase() and populated while parsing the sqfpsql options tags in spfsql3.SPFTaskBase.parseTaskOptions().
        """
        super(self.__class__, self).__init__()
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        self.errMsg = "Perform_Pre_BulkLoadData not implemented for this handler"
        self.params_missing_errMsg = "Insufficient parameters for 'Bulk load' operation. '{0}' option should be provided"
        
        self.bulkload_input_file = queryOptions.BULKLOAD_PATH
        self.bulkload_source_cols = queryOptions.BULKLOAD_FIELDS
        self.bulkload_dest_cols = queryOptions.BULKLOAD_COLS
        self.bulkload_dest_tablename = queryOptions.BULKLOAD_TABLE
        self.bulkload_purge = queryOptions.BULKLOAD_PURGE
        self.bulkload_commitsize = queryOptions.BULKLOAD_COMMITSIZE
        self.bulkload_readchunksize = queryOptions.BULKLOAD_READCHUNKSIZE
        #self.bulkload_if_newCon = _bulkload_if_newCon
        #endregion locals

        self.logger.debug("{0} - _bulkload_input_file : {1}".format(calling_func, self.bulkload_input_file))
        self.logger.debug("{0} - _bulkload_source_cols : {1}".format(calling_func, self.bulkload_source_cols))
        self.logger.debug("{0} - _bulkload_dest_cols : {1}".format(calling_func, self.bulkload_dest_cols))
        self.logger.debug("{0} - _bulkload_dest_tablename : {1}".format(calling_func,self.bulkload_dest_tablename))
        self.logger.debug("{0} - _bulkload_purge : {1}".format(calling_func, self.bulkload_purge))
        #self.logger.debug("{0} - _bulkload_if_newCon : {1}".format(calling_func, _bulkload_if_newCon))

    #region properties
    @property
    def ready_for_purge_processing(self):
        """
        get : flag : whether ready to perform BULKLOAD -- purge data
        True -- indicates all required input validated and ready for BULKLOAD purge
        """
        if [self.bulkload_dest_tablename, self.bulkload_purge] == ["", False]:
            #no arguments present for bulk loading
            return False
        
        self.ConsoleWithTimeStamp("\n  Bulkload purge data utility, v 1.0")        
        self.ConsStar80()
        self.Console("  Destination Table   : {0}".format(self.bulkload_dest_tablename))
        self.Console("  Purge data          : {0}".format(self.bulkload_purge))
        self.ConsStar80()
        #self.Console()

        if self.IsEmptyOrNone(self.bulkload_dest_tablename) is True:
            errMsg = f"Invalid value provided for BULKLOAD_TABLE : {self.bulkload_dest_tablename}"
            raise Exception(errMsg)

        return True
    @property
    def ready_for_upload_processing(self):
        """
        get : flag : whether ready to perform BULKLOAD -- upload data
        True -- indicates all required input validated and ready for BULKLOAD -- upload
        """

        if [self.bulkload_input_file, self.bulkload_source_cols, self.bulkload_dest_cols, self.bulkload_dest_tablename] == ["", None, None, ""]:
            #no arguments present for bulk loading
            return False
        
        self.ConsoleWithTimeStamp("\n  Bulkload upload data utility, v 1.0")  
        self.ConsStar80()
        self.Console("  Source File         : {0}".format(self.bulkload_input_file))
        self.Console("  Source Fields       : {0}".format(self.bulkload_source_cols))
        self.Console("  Destination Table   : {0}".format(self.bulkload_dest_tablename))
        self.Console("  Destination Columns : {0}".format(self.bulkload_dest_cols))
        self.Console("  Purge Data          : {0}".format(self.bulkload_purge))
        self.Console("  Read Chunk Size     : {0}".format(self.bulkload_readchunksize))
        self.Console("  Commit Chunk Size   : {0}".format(self.bulkload_commitsize))
        self.ConsStar80()
        #self.Console()

        #validate BULKLOAD_PATH is valid file
        try: 
            if Path(self.bulkload_input_file).is_file() is False:
                errMsg = f"File not found - BULKLOAD_PATH : {self.bulkload_input_file}"
                raise Exception(errMsg)
        except TypeError as typErr:
            errMsg = f"Invalid input file name provided for BULKLOAD_PATH : {self.bulkload_input_file}"
            raise Exception(errMsg)
        
        if self.bulkload_source_cols in [None, "", []]:
            errMsg = f"Invalid value provided for BULKLOAD_FIELDS : {self._bulkload_source_cols}"
            raise Exception(errMsg)
        
        if self.bulkload_dest_cols in [None, "", []]:
            errMsg = f"Invalid value provided for BULKLOAD_COLS : {self.bulkload_dest_cols}"
            raise Exception(errMsg)

        if len(self.bulkload_source_cols) > len(self.bulkload_dest_cols):
            errMsg = f"Source fields '{len(self.bulkload_source_cols)}' are more than destination columns '{len(self.bulkload_dest_cols)}'"
            raise Exception(errMsg)

        if len(self.bulkload_source_cols) < len(self.bulkload_dest_cols):
            errMsg = f"Source fields {len(self.bulkload_source_cols)} are less than destination columns {len(self.bulkload_dest_cols)}"
            raise Exception(errMsg)

        if self.bulkload_dest_tablename in [None, ""]:
            errMsg = f"Invalid value provided for BULKLOAD_TABLE : {self.bulkload_dest_tablename}"
            raise Exception(errMsg)

        

        return True

    __bulkload_source_cols = None
    @property
    def bulkload_source_cols(self):
        """
        get : "list of" columns in source file with DT
        e.g., [col1, col2]
        """

        if self.bulkload_dest_cols in [None,"",[]]:
            return None
        else:
            tmp_bulkload_dest_cols = self.get_cols_DTList(self.bulkload_dest_cols) 
        temp_source_cols = [ f"{item[0]} {item[1]}" for item in list(zip(self.__bulkload_source_cols, tmp_bulkload_dest_cols))]
        return temp_source_cols

    @bulkload_source_cols.setter
    def bulkload_source_cols(self, value):
        """
        get : list of columns in source file with DT. The DT is determined from 
        e.g., "col1, col2" --> [col1 (c), col2 (n)]
        """
        if self.IsEmptyOrNone(value) is False:
            self.__bulkload_source_cols = self.parseDelimitedStringAsList(value)

    __bulkload_dest_cols = None
    @property
    def bulkload_dest_cols(self):
        """
        get : list of DT of column in source file
        e.g., [col1 (c), col2 (n)]
        """
        return self.__bulkload_dest_cols

    @bulkload_dest_cols.setter
    def  bulkload_dest_cols(self, value):
        if self.IsEmptyOrNone(value) is False:
            self.__bulkload_dest_cols = self.parseDelimitedStringAsList(value)

    #endregion properties

    def get_cols_WithoutDTList(self, colListWithDT):
        """
        get only columns without DT info
        [col1 (c), col2 (n)] --> [col1, col2]
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        rePtrn = r"(?P<colname>.*?)\s*?\((?P<DT>.)\)$"
        col_output = []
        #endregion locals
        self.logger.debug("{0} - colListWithDT : {1}".format(calling_func, colListWithDT))
        for item in colListWithDT:
            #self.logger.debug("{0} - item : {1}".format(calling_func, item))
            myMatch = re.match(rePtrn, item, re.IGNORECASE)
            if myMatch:
                colname = myMatch.group('colname')
            else:
                colname = item
            #self.logger.debug("{0} - colname : {1}".format(calling_func, colname))
            col_output.append(colname)
        self.logger.debug("{0} - col_output : {1}".format(calling_func, col_output))
        return col_output

    def get_cols_DTList(self, colListWithDT):
        """
        get only DT of the columns
        [col1 (c), col2 (n)] --> [(c), (n)]
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        rePtrn = r"(?P<colname>.*?)\s*?(?P<DT>\(.\))$"
        dt_output = []
        #endregion locals
        self.logger.debug("{0} - colListWithDT : {1}".format(calling_func, colListWithDT))
        if colListWithDT is None:
            return dt_output

        for item in colListWithDT:
            #self.logger.debug("{0} - item : {1}".format(calling_func, item))
            myMatch = re.match(rePtrn, item, re.IGNORECASE)
            if myMatch:
                dt1 = myMatch.group('DT')
            else:
                dt1 = '(c)'
            #self.logger.debug("{0} - dt1 : {1}".format(calling_func, dt1))
            dt_output.append(dt1)
        self.logger.debug("{0} - dt_output : {1}".format(calling_func, dt_output))
        return dt_output

    def get_cols_DTDict(self, colListWithDT):
        """
        Transform list column with DT into Dictionary for Pandas DT
        ['col1 (c)', 'col2 (n)'] --> {'col1' : '(c)', 'col2' : '(n)'}
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        rePtrn = r"(?P<colname>.*?)\s*?\((?P<DT>.)\)$"
        #map of SQLPF DT with pandas DT
        PDDF_DT_Map = {"n" : "int64",
                       "f" : "float64",
                       "default_DT" : 'str' #default pandas dataframe datatype
                       } 

        dt_output = {}
        #endregion locals
        self.logger.debug("{0} - colListWithDT : {1}".format(calling_func, colListWithDT))
        for item in colListWithDT:
            #self.logger.debug("{0} - item : {1}".format(calling_func, item))
            myMatch = re.match(rePtrn, item, re.IGNORECASE)
            if myMatch:
                colName, dt1 = (myMatch.group('colname'), myMatch.group('DT'))
            else:
                colName, dt1 = (item, 'c')
            #get the pandas datatype for the column
            try:
                dt1 = PDDF_DT_Map[dt1]
            except KeyError as keyErr:
                #data type not found in map
                dt1 = PDDF_DT_Map["default_DT"]
            #self.logger.debug("{0} - dt1 : {1}".format(calling_func, dt1))
            # add to output dict
            dt_output[colName] = dt1
        self.logger.debug("{0} - dt_output : {1}".format(calling_func, dt_output))
        return dt_output

    def uploadData(self, conObj):
        """
        perform bulk load into DB 
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        if self.ready_for_upload_processing is True:
            try:
                sourceFileReadChunkSize=self.bulkload_readchunksize
                self.logger.debug("{0} - sourceFileReadChunkSize : {1}".format(calling_func, sourceFileReadChunkSize)) 

                dbCommitSize = self.bulkload_commitsize
                self.logger.debug("{0} - dbCommitSize : {1}".format(calling_func, dbCommitSize)) 
                
                fileNameWithPath = self.bulkload_input_file
                fileDLM = self.GetFileDLM(fileNameWithPath)
                pddf_dt = self.get_cols_DTDict(self.bulkload_source_cols)
                #create destination colnNames for insert stmnt
                destColNamesList = self.get_cols_WithoutDTList(self.bulkload_dest_cols)
                destColNamesForInsertStmnt = ",".join(destColNamesList)
                self.logger.debug("{0} - destColNamesList : {1}".format(calling_func, destColNamesList))   
                self.logger.debug("{0} - destColNamesForInsertStmnt : {1}".format(calling_func, destColNamesForInsertStmnt))             
                sourceColNamesList = self.get_cols_WithoutDTList(self.bulkload_source_cols)
                sourceColNamesForInsertStmnt = ",".join([f":{col}" for col in sourceColNamesList])
                self.logger.debug("{0} - sourceColNamesList : {1}".format(calling_func, sourceColNamesList)) 
                self.logger.debug("{0} - sourceColNamesForInsertStmnt : {1}".format(calling_func, sourceColNamesForInsertStmnt)) 

                deleteRowsStmnt = "DELETE FROM {0}".format(self.bulkload_dest_tablename)
                self.logger.debug("{0} - deleteRowsStmnt : '{1}'".format(calling_func, deleteRowsStmnt))
                
                insertStmnt = "INSERT INTO {0} ({1}) values ({2})".format(self.bulkload_dest_tablename,
                                                                            destColNamesForInsertStmnt,
                                                                            sourceColNamesForInsertStmnt)

                self.logger.debug("{0} - insertStmnt : '{1}'".format(calling_func, insertStmnt))

                if conObj is None:
                    invalidConObj_errMsg = "Invalid connection object : '{0}'".format(conObj)
                else: 
                    conObj.autocommit = False
                    curDB = conObj.cursor()
                    self.logger.debug("{0} - Cursor created from conObj parameter".format(calling_func))

                #run delete rows statement
                curDB.execute(deleteRowsStmnt)
                #conObj.connectionObject.commit()
                rowCount = 0
                commitRowcount = 0
                chunkcount = 0
                try:
                    myReader = pd.read_csv(filepath_or_buffer=fileNameWithPath, sep=fileDLM,usecols=sourceColNamesList, skipinitialspace=False
                                           , iterator=True, chunksize=sourceFileReadChunkSize, keep_default_na=False
                                           , header=0, dtype=pddf_dt)
                    for item in myReader:
                        self.logger.debug("{0} - df dict : '{1}'".format(calling_func, item.to_dict('records')))
                        chunkcount = chunkcount + 1
                        try:
                            curDB.executemany(insertStmnt, item.to_dict('records'))
                            rowCount = rowCount + len(item)  
                            commitRowcount = commitRowcount + len(item)
                            if commitRowcount >= dbCommitSize:
                                conObj.commit() #commit the data 
                                commitRowcount = 0
                                self.logger.debug("{0} - Commit Done - Chunk : {1} ".format(calling_func, chunkcount))
                        except Exception as err:
                            raise
                except ValueError as valErr                :
                    self.logger.exception("{0} -{1}".format(calling_func, valErr))
                    errMsg = f"Please check if the datatype specified for columns is correct.\n Error: {valErr}"
                    raise Exception(errMsg)
                except Exception as err:
                    raise
                #close the cursor
                curDB.close()
                curDB = None

                if conObj is not None :
                    conObj.commit() #commit the data 
                    self.logger.debug("{0} - Commit Done - Total record count : {1}".format(calling_func, rowCount))
                self.ConsoleDoneWithTimeStamp()
                return rowCount

            except Exception as err:
                self.logger.exception("{0} -{1}".format(calling_func, err))
                raise

    def purgeData(self, conObj):
        """
        perform purge of bulk loaded data
        """
        #region locals
        calling_func = self.getCallingFuncName(2, self.__class__.__name__)
        #raise Exception("Not implemented")
        if self.ready_for_purge_processing is True:
            try:
                if self.bulkload_purge is True:
                    deleteRowsStmnt = "DELETE FROM {0}".format(self.bulkload_dest_tablename)
                    self.logger.debug("{0} - deleteRowsStmnt : '{1}'".format(calling_func, deleteRowsStmnt))
                    if conObj is None:
                        invalidConObj_errMsg = "Invalid connection object : '{0}'".format(conObj)
                    else: 
                        conObj.autocommit = False
                        curDB = conObj.cursor()
                        self.logger.debug("{0} - Cursor created from conObj parameter".format(calling_func))

                    #run delete rows statement
                    curDB.execute(deleteRowsStmnt)
            
                    #close the cursor
                    curDB.close()
                    curDB = None

                    if conObj is not None :
                        conObj.commit() #commit the data if this is referring to an external SQLite DB 
                        self.logger.debug("{0} - Commit Done - conObj".format(calling_func))
                    self.ConsoleDoneWithTimeStamp()
            except Exception as err:
                self.logger.exception("{0} -{1}".format(calling_func, err))
                raise
#END : class BulkloadDataHandler:    

class SPFRichProgressBar(RichProgressBar):
    """
    custom implementation of ProgressBar provided by rich.progress.Progress
    """
    def __init__(self, *columns: Union[str, RichProgressColumn], console: Union[RichConsole, None] = None, auto_refresh: bool = True, 
                 refresh_per_second: float = 10, speed_estimate_period: float = 30, transient: bool = False, 
                 redirect_stdout: bool = True, redirect_stderr: bool = True, get_time: Union[RichGetTimeCallable, None] = None, 
                 disable: bool = False, expand: bool = False, displayMofN=True) -> None:
        if columns == ():
            # RichTextColumn(""),
            if displayMofN is True:
                columns = [*RichProgressBar.get_default_columns()[:-1], RichTextColumn("•"), RichMofNCompleteColumn(), RichTextColumn("•") ,RichTimeElapsedColumn(), RichSpinnerColumn(spinner_name = "earth", finished_text= "", style="skyblue")]
            else:
                columns = [*RichProgressBar.get_default_columns()[:-1], RichTextColumn("•"), RichTimeElapsedColumn(), RichSpinnerColumn(spinner_name = "earth", finished_text= "", style="skyblue")]
        super().__init__(*columns, console=console, auto_refresh=auto_refresh, refresh_per_second=refresh_per_second, speed_estimate_period=speed_estimate_period, transient=transient, redirect_stdout=redirect_stdout, redirect_stderr=redirect_stderr, get_time=get_time, disable=disable, expand=expand)
        return
    
    def add_task(self, description: str, start: bool = True, total: Union[float, None] = 100, completed: int = 0, visible: bool = True, **fields: Any) -> RichTaskID:
        # description = f"[purple]  {description}..."
        description = f"  {description}..."
        return super().add_task(description, start, total, completed, visible, **fields)
#END : class SPFRichProgressBar
